    'ສະບາຍດີ 🙏 ບອກພວກເຮົາວ່າຮ້ານຂອງທ່ານຕ້ອງການຫຍັງ — ພິມ ຫຼື ກົດໄມໂຄຣໂຟນເພື່ອສົ່ງສຽງກໍໄດ້. ຖາມໄດ້ທັນທີ ບໍ່ຕ້ອງລົງທະບຽນ.' => 'สวัสดี 🙏 บอกเราว่าร้านของคุณต้องการอะไร — พิมพ์ หรือกดไมโครโฟนเพื่อส่งเสียงก็ได้ ถามได้ทันที ไม่ต้องลงทะเบียน',
    'ຝາກເບີໂທ ໃຫ້ທີມງານໂທກັບ:' => 'ฝากเบอร์โทรให้ทีมงานโทรกลับ:',
