    'ບຣາວເຊີນີ້ອັດສຽງບໍ່ໄດ້' => 'เบราว์เซอร์นี้อัดเสียงไม่ได้',
    'ກະລຸນາອະນຸຍາດໃຫ້ໃຊ້ໄມໂຄຣໂຟນ' => 'กรุณาอนุญาตให้ใช้ไมโครโฟน',
