    'ອັດສຽງໄດ້ສະເພາະເວັບທີ່ເປັນ https (ຫຼື localhost) — ກະລຸນາພິມຂໍ້ຄວາມແທນ' => 'อัดเสียงได้เฉพาะเว็บ https (หรือ localhost) — กรุณาพิมพ์ข้อความแทน',
    'ບໍ່ໄດ້ຍິນສຽງຈາກໄມໂຄຣໂຟນ — ກວດເບິ່ງວ່າເລືອກໄມຖືກ ແລະ ບໍ່ໄດ້ປິດສຽງ ແລ້ວລອງໃໝ່' => 'ไม่ได้ยินเสียงจากไมโครโฟน — ตรวจสอบว่าเลือกไมถูกและไม่ได้ปิดเสียง แล้วลองใหม่',
    'ຂໍເສັ້ນທາງມາຮ້ານ' => 'ขอเส้นทางมาร้าน',
