    'ກຳລັງສົ່ງຕຳແໜ່ງ…' => 'กำลังส่งตำแหน่ง…',
    'ສົ່ງຕຳແໜ່ງໄດ້ສະເພາະເວັບທີ່ເປັນ https (ຫຼື localhost) — ກົດ "ຂໍເສັ້ນທາງມາຮ້ານ" ແທນ' => 'ส่งตำแหน่งได้เฉพาะเว็บ https (หรือ localhost) — กด "ขอเส้นทางมาร้าน" แทน',
    'ບໍ່ໄດ້ຮັບຕຳແໜ່ງ — ກະລຸນາອະນຸຍາດໃຫ້ເວັບໃຊ້ຕຳແໜ່ງ (Location) ແລ້ວລອງໃໝ່' => 'ไม่ได้รับตำแหน่ง — กรุณาอนุญาตให้เว็บใช้ตำแหน่ง แล้วลองใหม่',
    'ຕຳແໜ່ງຂອງຂ້ອຍ' => 'ตำแหน่งของฉัน',
    'ປະມານ %d ແມັດ' => 'ประมาณ %d เมตร',
    'ປະມານ %s ກມ' => 'ประมาณ %s กม.',
    'ໄດ້ຮັບຕຳແໜ່ງແລ້ວ 🙏 ທ່ານຢູ່ຫ່າງຈາກຮ້ານ %s (ເສັ້ນຊື່). ກົດລິ້ງນີ້ເພື່ອນຳທາງມາຮ້ານ:' => 'ได้รับตำแหน่งแล้ว 🙏 คุณอยู่ห่างจากร้าน %s (เส้นตรง) กดลิงก์นี้เพื่อนำทางมาร้าน:',
    'ທີ່ຢູ່ຮ້ານ: %s — ເປີດ ຈັນ–ເສົາ 8:30–17:00' => 'ที่อยู่ร้าน: %s — เปิด จ.–ส. 8:30–17:00',
    'ກົດລິ້ງນີ້ເພື່ອໃຫ້ Google Maps ນຳທາງມາຮ້ານຈາກບ່ອນທ່ານຢູ່:' => 'กดลิงก์นี้ให้ Google Maps นำทางมาร้านจากที่คุณอยู่:',
    'ຫຼື ກົດປຸ່ມສົ່ງຕຳແໜ່ງ ເພື່ອສົ່ງຕຳແໜ່ງຂອງທ່ານ ແລ້ວພວກເຮົາຈະບອກໄລຍະທາງໃຫ້.' => 'หรือกดปุ่ม เพื่อส่งตำแหน่งของคุณ แล้วเราจะบอกระยะทางให้',
    'ນຳທາງມາຮ້ານ:' => 'นำทางมาร้าน:',
    'ຕຳແໜ່ງບໍ່ຖືກຕ້ອງ' => 'ตำแหน่งไม่ถูกต้อง',
    'ໄດ້ແຈ້ງພະນັກງານແລ້ວ 🙏 ທີມງານຈະເຂົ້າມາຕອບໃນແຊັດນີ້ໄວໆ (ຈັນ–ເສົາ 8:30–17:00).' => 'แจ้งพนักงานแล้ว 🙏 ทีมงานจะเข้ามาตอบในแชทนี้เร็วๆ นี้ (จ.–ส. 8:30–17:00)',
    'ລົບກວນຝາກຊື່ ແລະ ເບີໂທໄວ້ ເພື່ອໃຫ້ພວກເຮົາໂທກັບໄດ້.' => 'รบกวนฝากชื่อและเบอร์โทรไว้ เพื่อให้เราโทรกลับได้',
    'ລົບກວນຝາກຊື່ ແລະ ເບີໂທໄວ້ ທີມງານຈະໂທກັບພາຍໃນ 24 ຊົ່ວໂມງ.' => 'รบกวนฝากชื่อและเบอร์โทรไว้ ทีมงานจะโทรกลับภายใน 24 ชั่วโมง',
    'ລາຄາຂຶ້ນກັບປະເພດຮ້ານ, ຈຳນວນເຄື່ອງ ແລະ ອຸປະກອນທີ່ຕ້ອງການ — ທີມງານຈະສົ່ງໃບສະເໜີລາຄາທີ່ເໝາະກັບງົບປະມານຂອງທ່ານ.' => 'ราคาขึ้นอยู่กับประเภทร้าน จำนวนเครื่อง และอุปกรณ์ที่ต้องการ — ทีมงานจะส่งใบเสนอราคาที่เหมาะกับงบประมาณของคุณ',
    'ອຸປະກອນ POS ທີ່ພວກເຮົາມີ: %s. ເບິ່ງລາຍລະອຽດໄດ້ທີ່ໜ້າ "ອຸປະກອນ POS".' => 'อุปกรณ์ POS ที่เรามี: %s ดูรายละเอียดได้ที่หน้า "อุปกรณ์ POS"',
    'ພວກເຮົາມີລະບົບ POS ສຳລັບ: %s. ຮ້ານຂອງທ່ານເປັນປະເພດໃດ, ມີຈັກສາຂາ?' => 'เรามีระบบ POS สำหรับ: %s ร้านของคุณเป็นประเภทไหน มีกี่สาขา?',
    'ພວກເຮົາເຮັດເວັບໄຊບໍລິສັດ ແລະ ເວັບຂາຍສິນຄ້າອອນລາຍ ທີ່ເຊື່ອມກັບສະຕັອກ POS ໄດ້, ຮອງຮັບມືຖື ແລະ ຫຼາຍພາສາ.' => 'เราทำเว็บไซต์บริษัทและร้านค้าออนไลน์ที่เชื่อมกับสต็อก POS ได้ รองรับมือถือและหลายภาษา',
    'ຮ້ານຢູ່ %s, ເປີດ ຈັນ–ເສົາ 8:30–17:00.' => 'ร้านอยู่ที่ %s เปิด จ.–ส. 8:30–17:00',
    'ໂທ %s, WhatsApp +856 20 55 949 007 / +856 20 95 321 848 ຫຼື Facebook Page "Wlaodev".' => 'โทร %s, WhatsApp +856 20 55 949 007 / +856 20 95 321 848 หรือ Facebook Page "Wlaodev"',
    'ສະບາຍດີ 🙏 ຢາກໄດ້ລະບົບ POS, ອຸປະກອນ ຫຼື ເວັບໄຊ ສຳລັບຮ້ານແບບໃດ? ຖາມໄດ້ເລີຍ.' => 'สวัสดีครับ 🙏 ต้องการระบบ POS อุปกรณ์ หรือเว็บไซต์ สำหรับร้านแบบไหน? ถามได้เลย',
    'ຍິນດີຊ່ວຍເຫຼືອ 🙏 ມີຫຍັງສົງໄສ ຖາມໄດ້ຕະຫຼອດ.' => 'ยินดีช่วยเหลือ 🙏 มีอะไรสงสัย ถามได้ตลอด',
    'ຂອບໃຈສຳລັບຂໍ້ຄວາມ 🙏 ທີມງານຈະອ່ານ ແລະ ຕອບກັບໃນແຊັດນີ້ໄວໆ.' => 'ขอบคุณสำหรับข้อความ 🙏 ทีมงานจะอ่านและตอบกลับในแชทนี้เร็วๆ นี้',
    'ຂອບໃຈ%s 🙏 ໄດ້ບັນທຶກເບີໂທແລ້ວ ທີມງານຈະໂທກັບພາຍໃນ 24 ຊົ່ວໂມງ. ມີຫຍັງຖາມຕໍ່ໄດ້ເລີຍ.' => 'ขอบคุณ%s 🙏 บันทึกเบอร์โทรแล้ว ทีมงานจะโทรกลับภายใน 24 ชั่วโมง มีอะไรถามต่อได้เลย',
    'ໄດ້ຮັບຂໍ້ຄວາມສຽງແລ້ວ ພະນັກງານຈະຟັງ ແລະ ຕອບກັບໃນແຊັດນີ້ໄວໆ.' => 'ได้รับข้อความเสียงแล้ว พนักงานจะฟังและตอบกลับในแชทนี้เร็วๆ นี้',
    'ບ້ານ ໂນນຄໍ້ເໜືອ ເມືອງ ໄຊເສດຖາ ນະຄອນຫຼວງວຽງຈັນ' => 'บ้านโนนค้อเหนือ เมืองไซเสดถา นครหลวงเวียงจันทน์',
    'ສະມາຊິກເລກທີ %d' => 'สมาชิกเลขที่ %d',
    'ກະລຸນາປ້ອນເບີໂທໃຫ້ຖືກຕ້ອງ' => 'กรุณากรอกเบอร์โทรให้ถูกต้อง',
    'ລະຫັດຜ່ານຕ້ອງມີຢ່າງໜ້ອຍ 6 ຕົວ' => 'รหัสผ่านต้องมีอย่างน้อย 6 ตัว',
    'ລະຫັດຜ່ານທັງສອງບໍ່ກົງກັນ' => 'รหัสผ่านทั้งสองไม่ตรงกัน',
    'ເບີໂທນີ້ສະໝັກແລ້ວ — ກະລຸນາເຂົ້າສູ່ລະບົບ' => 'เบอร์โทรนี้สมัครแล้ว — กรุณาเข้าสู่ระบบ',
    'ສະໝັກບໍ່ສຳເລັດ ກະລຸນາລອງໃໝ່' => 'สมัครไม่สำเร็จ กรุณาลองใหม่',
    'ລອງຜິດຫຼາຍເທື່ອ ກະລຸນາລໍຖ້າ %d ນາທີ' => 'ลองผิดหลายครั้ง กรุณารอ %d นาที',
    'ເບີໂທ ຫຼື ລະຫັດຜ່ານບໍ່ຖືກຕ້ອງ' => 'เบอร์โทรหรือรหัสผ่านไม่ถูกต้อง',
    'ບັນຊີນີ້ຖືກປິດໃຊ້ງານ ກະລຸນາຕິດຕໍ່ພວກເຮົາ' => 'บัญชีนี้ถูกปิดใช้งาน กรุณาติดต่อเรา',
    'ສະໝັກສະມາຊິກ' => 'สมัครสมาชิก',
    'ສະໝັກຟຣີ — ໄດ້ເລກສະມາຊິກ ແລະ ບໍ່ຕ້ອງປ້ອນຊື່/ເບີໂທຊ້ຳທຸກຄັ້ງທີ່ສັ່ງຊື້ ຫຼື ແຊັດ' => 'สมัครฟรี — ได้เลขสมาชิก และไม่ต้องกรอกชื่อ/เบอร์โทรซ้ำทุกครั้งที่สั่งซื้อหรือแชท',
    'ສະໝັກສຳເລັດ! ທ່ານແມ່ນສະມາຊິກເລກທີ %d' => 'สมัครสำเร็จ! คุณคือสมาชิกเลขที่ %d',
    'ເບີໂທ * (ໃຊ້ເຂົ້າສູ່ລະບົບ)' => 'เบอร์โทร * (ใช้เข้าสู่ระบบ)',
    'ລະຫັດຜ່ານ * (ຢ່າງໜ້ອຍ 6 ຕົວ)' => 'รหัสผ่าน * (อย่างน้อย 6 ตัว)',
    'ຢືນຢັນລະຫັດຜ່ານ *' => 'ยืนยันรหัสผ่าน *',
    'ມີບັນຊີແລ້ວ?' => 'มีบัญชีแล้ว?',
    'ເຂົ້າສູ່ລະບົບສະມາຊິກ' => 'เข้าสู่ระบบสมาชิก',
