    'ກະລຸນາເລືອກທະນາຄານທີ່ໂອນເງິນ' => 'กรุณาเลือกธนาคารที่โอนเงิน',
    'ກະລຸນາແນບຮູບສະລິບການໂອນເງິນ' => 'กรุณาแนบรูปสลิปการโอนเงิน',
    'ອັບໂຫຼດຮູບສະລິບບໍ່ສຳເລັດ ກະລຸນາລອງໃໝ່' => 'อัปโหลดสลิปไม่สำเร็จ กรุณาลองใหม่',
    'ຂະໜາດຮູບສະລິບຕ້ອງບໍ່ເກີນ 8 MB' => 'ขนาดรูปสลิปต้องไม่เกิน 8 MB',
    'ຮອງຮັບສະເພາະໄຟລ໌ຮູບພາບ JPG, PNG ຫຼື WEBP' => 'รองรับเฉพาะไฟล์รูป JPG, PNG หรือ WEBP',
    'ບັນທຶກຮູບສະລິບບໍ່ສຳເລັດ' => 'บันทึกรูปสลิปไม่สำเร็จ',
    'ບ້ານ ' => 'บ้าน ',
    'ເມືອງ ' => 'เมือง ',
    'ບໍ່ພົບສິນຄ້ານີ້ ຫຼື ຢຸດຂາຍແລ້ວ' => 'ไม่พบสินค้านี้ หรือหยุดขายแล้ว',
    'ລະບົບຂາຍໜ້າຮ້ານສຳຜັດງ່າຍ ສຳລັບຮ້ານກາເຟ, ຊານົມໄຂ່ມຸກ ແລະ ເຄື່ອງດື່ມທຸກປະເພດ' => 'ระบบขายหน้าร้านแบบสัมผัสง่าย สำหรับร้านกาแฟ ชานมไข่มุก และเครื่องดื่มทุกประเภท',
    'ລະບົບ POS ຮ້ານເຄື່ອງດື່ມ ແລະ ຄາເຟ ອອກແບບມາເພື່ອຄວາມໄວ ແລະ ຄວາມຖືກຕ້ອງ: ຮັບອໍເດີໜ້າຮ້ານໄດ້ໄວ, ເລືອກລະດັບຄວາມຫວານ, ນ້ຳກ້ອນ ແລະ ທັອບປິ້ງໄດ້ລະອຽດ, ພິມໃບສັ່ງເຂົ້າບາຣ໌ນ້ຳອັດຕະໂນມັດ, ຕັ້ງໂປຣໂມຊັ່ນ, ແລະ ເບິ່ງຍອດຂາຍ Real-time ຜ່ານມືຖື.' => 'ระบบ POS ร้านเครื่องดื่มและคาเฟ่ ออกแบบเพื่อความเร็วและความถูกต้อง: รับออเดอร์ไว เลือกระดับความหวาน น้ำแข็ง ท็อปปิ้ง พิมพ์ใบสั่งเข้าบาร์อัตโนมัติ ตั้งโปรโมชั่น และดูยอดขาย Real-time ผ่านมือถือ',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານສຳຜັດງ່າຍ ເມນູພາບງາມ ເລືອກທັອບປິ້ງ ແລະ ລະດັບຄວາມຫວານ' => 'หน้าจอขายแบบสัมผัสง่าย เมนูรูปสวย เลือกท็อปปิ้งและระดับความหวาน',
    'ເຄື່ອງ POS Dual Screen Touchscreen, ປິ້ນເຕີໃບບິນ ແລະ ລິ້ນຊັກເກັບເງິນ' => 'เครื่อง POS จอสัมผัส Dual Screen เครื่องพิมพ์ใบเสร็จ และลิ้นชักเก็บเงิน',
    'ໂປຣແກຣມ POS ທັນສະໄໝ ຮອງຮັບຈໍສຳຜັດ Smart Touch ແລະ ແຍກໂຕະ' => 'โปรแกรม POS ทันสมัย รองรับจอสัมผัส Smart Touch และแยกโต๊ะ',
    'ລະບົບຄິດເງິນ ແລະ ອອກໃບບິນພາສາລາວສະດວກວ່ອງໄວ' => 'ระบบคิดเงินและออกใบเสร็จภาษาลาวสะดวกรวดเร็ว',
    'ຮັບອໍເດີ ແລະ ຄິດເງິນໄວຂຶ້ນ 3 ເທົ່າ' => 'รับออเดอร์และคิดเงินเร็วขึ้น 3 เท่า',
    'ໜ້າຈໍສຳຜັດຂະໜາດໃຫຍ່ ເມນູແບ່ງໝວດຊັດເຈນ ກົດສັ່ງໄດ້ໄວ ລູກຄ້າບໍ່ຕ້ອງລໍຖ້າຄິວດົນ ຫຼຸດຄວາມຜິດພາດໃນການສັ່ງເຄື່ອງດື່ມ.' => 'จอสัมผัสขนาดใหญ่ เมนูแบ่งหมวดชัดเจน กดสั่งได้เร็ว ลูกค้าไม่ต้องรอคิวนาน ลดความผิดพลาดในการสั่งเครื่องดื่ม',
    'ພິມບິນເຂົ້າບາຣ໌ນ້ຳອັດຕະໂນມັດ ບໍ່ມີອໍເດີຕົກຫຼົ່ນ' => 'พิมพ์บิลเข้าบาร์น้ำอัตโนมัติ ไม่มีออเดอร์ตกหล่น',
    'ເມື່ອແຄັດເຊຍກົດຮັບອໍເດີ, ລະບົບຈະສົ່ງລາຍການໄປພິມທີ່ເຄົາເຕີ້ຊົງນ້ຳທັນທີ ພະນັກງານຊົງນ້ຳເຮັດວຽກໄດ້ຕໍ່ເນື່ອງ ບໍ່ຕ້ອງຮ້ອງບອກ.' => 'เมื่อแคชเชียร์กดรับออเดอร์ ระบบจะพิมพ์รายการที่เคาน์เตอร์ชงทันที พนักงานชงทำงานต่อเนื่อง ไม่ต้องตะโกนบอก',
    'ຕັ້ງໂປຣໂມຊັ່ນເອງ ລະບົບຄິດສ່ວນຫຼຸດໃຫ້ອັດຕະໂນມັດ' => 'ตั้งโปรโมชั่นเอง ระบบคิดส่วนลดให้อัตโนมัติ',
    'ຕັ້ງສ່ວນຫຼຸດຕາມສິນຄ້າ ຫຼື ໝວດ ພ້ອມວັນໝົດອາຍຸ ລະບົບຄິດລາຄາໃຫ້ເອງຕອນຂາຍ ແລະ ປິດໂປຣເອງເມື່ອໝົດເວລາ.' => 'ตั้งส่วนลดตามสินค้าหรือหมวด พร้อมวันหมดอายุ ระบบคิดราคาให้เองตอนขาย และปิดโปรเองเมื่อหมดเวลา',
    'ເບິ່ງຍອດຂາຍ ແລະ ກຳໄລ Real-time ຜ່ານມືຖື' => 'ดูยอดขายและกำไร Real-time ผ่านมือถือ',
    'ເຈົ້າຂອງຮ້ານບໍ່ຈຳເປັນຕ້ອງຢູ່ຮ້ານຕະຫຼອດເວລາ ສາມາດກວດເບິ່ງຍອດຂາຍ, ຈຳນວນບິນ, ເມນູຂາຍດີ ແລະ ກຳໄລສຸດທິໄດ້ 24 ຊົ່ວໂມງ.' => 'เจ้าของร้านไม่จำเป็นต้องอยู่ร้านตลอดเวลา ตรวจดูยอดขาย จำนวนบิล เมนูขายดี และกำไรสุทธิได้ 24 ชั่วโมง',
    'ປ້ອງກັນເງິນຕົກເຮ່ຍ ແລະ ກວດສອບຍອດເງິນໂປ່ງໃສ' => 'ป้องกันเงินรั่วไหล ตรวจสอบยอดเงินโปร่งใส',
    'ບັນທຶກທຸກການຮັບເງິນ, ແຍກກະການຂາຍ (Shift), ລັອກສິດການຍົກເລີກບິນ, ກວດສອບຍອດເງິນໃນລິ້ນຊັກໄດ້ຕະຫຼອດ.' => 'บันทึกทุกการรับเงิน แยกกะการขาย (Shift) ล็อกสิทธิ์ยกเลิกบิล ตรวจยอดเงินในลิ้นชักได้ตลอด',
    'ຮອງຮັບ Option ເສີມ: ລະດັບຄວາມຫວານ (0%, 25%, 50%, 100%), ນ້ຳກ້ອນ, ທັອບປິ້ງ (ໄຂ່ມຸກ, ວຸ້ນ, ພຸດດິ້ງ)' => 'รองรับตัวเลือกเสริม: ระดับความหวาน (0%, 25%, 50%, 100%) น้ำแข็ง ท็อปปิ้ง (ไข่มุก วุ้น พุดดิ้ง)',
    'ລະບົບເປີດໂຕະ, ພັກບິນ, ແຍກບິນ ແລະ ລວມບິນສຳລັບລູກຄ້ານັ່ງກິນໃນຮ້ານ' => 'เปิดโต๊ะ พักบิล แยกบิล และรวมบิล สำหรับลูกค้านั่งทานในร้าน',
    'ພິມໃບບິນພາສາລາວ ພ້ອມໂລໂກ້ຮ້ານຄ້າ' => 'พิมพ์ใบเสร็จภาษาลาวพร้อมโลโก้ร้าน',
    'ຮອງຮັບປິ້ນເຕີບາຣ໌ນ້ຳທັງແບບ LAN, Wi-Fi ແລະ Bluetooth' => 'รองรับเครื่องพิมพ์บาร์น้ำแบบ LAN, Wi-Fi และ Bluetooth',
    'ລະບົບສະສົມຄະແນນລູກຄ້າ ແລະ ສະມາຊິກ ເພີ່ມຍອດຂາຍຊ້ຳ' => 'ระบบสะสมคะแนนลูกค้าและสมาชิก เพิ่มยอดขายซ้ำ',
    'ເຮັດວຽກໄດ້ທັງ Offline (ເນັດຫຼຸດຍັງຂາຍຕໍ່ໄດ້) ແລະ Online Sync ຂໍ້ມູນ' => 'ทำงานได้ทั้ง Offline (เน็ตหลุดยังขายต่อได้) และ Online Sync ข้อมูล',
    'ລະບົບຂາຍໜ້າຮ້ານມິນິມາດ ສະແກນບາໂຄດໄວ ຈັດການສະຕັອກຫຼາຍພັນລາຍການ' => 'ระบบขายหน้าร้านมินิมาร์ท สแกนบาร์โค้ดเร็ว จัดการสต็อกหลายพันรายการ',
    'ລະບົບ POS ຮ້ານມິນິມາດ ອອກແບບມາຮອງຮັບການຂາຍສິນຄ້າອຸປະໂພກ-ບໍລິໂພກຂະໜາດໃຫຍ່: ສະແກນບາໂຄດໄວ, ຈັດການສິນຄ້າຫຼາຍກວ່າ 50,000+ ລາຍການ, ຄຸ້ມຄອງສະຕັອກ Real-time, ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດ, ແລະ ຮອງຮັບຫຼາຍສະກຸນເງິນ.' => 'ระบบ POS มินิมาร์ท รองรับสินค้าอุปโภคบริโภคจำนวนมาก: สแกนบาร์โค้ดเร็ว จัดการสินค้า 50,000+ รายการ สต็อก Real-time แจ้งเตือนสินค้าใกล้หมด และรองรับหลายสกุลเงิน',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານມິນິມາດ ສະແກນບາໂຄດໄວ ຄິດເງິນຫຼາຍສະກຸນ' => 'หน้าจอขายมินิมาร์ท สแกนบาร์โค้ดเร็ว คิดเงินหลายสกุล',
    'ເຄົາເຕີ້ຄິດເງິນມິນິມາດຄົບຊຸດ: ເຄື່ອງຍິງບາໂຄດ, ປິ້ນເຕີ ແລະ ລິ້ນຊັກເກັບເງິນ' => 'เคาน์เตอร์คิดเงินมินิมาร์ทครบชุด: เครื่องสแกนบาร์โค้ด เครื่องพิมพ์ และลิ้นชักเก็บเงิน',
    'ເຄື່ອງ POS Dual Screen Touchscreen ໜ້າຈໍໃຫຍ່ ສຳຜັດໄວ' => 'เครื่อง POS จอสัมผัส Dual Screen จอใหญ่ สัมผัสไว',
    'ລະບົບຄິດເງິນຄົບຊຸດ ແລະ ພິມໃບບິນພາສາລາວ' => 'ระบบคิดเงินครบชุดและพิมพ์ใบเสร็จภาษาลาว',
    'ສະແກນບາໂຄດໄວ ບໍ່ຕ້ອງຈື່ລາຄາສິນຄ້າ' => 'สแกนบาร์โค้ดเร็ว ไม่ต้องจำราคาสินค้า',
    'ຍິງບາໂຄດປຶບ ຊື່ສິນຄ້າ, ຮູບພາບ ແລະ ລາຄາຈະຂຶ້ນທັນທີ ຄິດເງິນໄດ້ວ່ອງໄວ ບໍ່ຜິດພາດ ແມ້ມີສິນຄ້າຫຼາຍພັນລາຍການ.' => 'สแกนปุ๊บ ชื่อสินค้า รูปภาพ และราคาขึ้นทันที คิดเงินเร็ว ไม่ผิดพลาด แม้มีสินค้าหลายพันรายการ',
    'ຄຸ້ມຄອງສະຕັອກ Real-time ປ້ອງກັນສິນຄ້າຫາຍ 100%' => 'ควบคุมสต็อก Real-time ป้องกันสินค้าหาย',
    'ຕັດສະຕັອກທຸກຄັ້ງທີ່ມີການຂາຍ ຮູ້ທັນທີວ່າສິນຄ້າໃດເຫຼືອເທົ່າໃດ, ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດສະຕັອກເພື່ອສັ່ງຊື້ເພີ່ມທັນເວລາ.' => 'ตัดสต็อกทุกครั้งที่ขาย รู้ทันทีว่าสินค้าไหนเหลือเท่าไร แจ้งเตือนสินค้าใกล้หมดเพื่อสั่งซื้อทันเวลา',
    'ຮອງຮັບຫຼາຍສະກຸນເງິນ (LAK, THB, USD, CNY)' => 'รองรับหลายสกุลเงิน (LAK, THB, USD, CNY)',
    'ຄິດເງິນ ແລະ ທອນເງິນໄດ້ທຸກສະກຸນເງິນຕາມອັດຕາແລກປ່ຽນປະຈຳວັນ ສະດວກສະບາຍສຳລັບລູກຄ້າທັງຄົນລາວ ແລະ ຊາວຕ່າງຊາດ.' => 'คิดเงินและทอนเงินได้ทุกสกุลตามอัตราแลกเปลี่ยนรายวัน สะดวกสำหรับลูกค้าทั้งคนลาวและชาวต่างชาติ',
    'ລາຍງານຍອດຂາຍ, ກຳໄລ ແລະ ສິນຄ້າຂາຍດີ' => 'รายงานยอดขาย กำไร และสินค้าขายดี',
    'ວິເຄາະໄດ້ວ່າສິນຄ້າໃດສ້າງກຳໄລສູງສຸດ, ສິນຄ້າໃດຄ້າງສະຕັອກຂາຍຊ້າ ຊ່ວຍໃຫ້ເຈົ້າຂອງຮ້ານຕັດສິນໃຈສັ່ງສິນຄ້າໄດ້ຢ່າງແມ່ນຍຳ.' => 'วิเคราะห์ได้ว่าสินค้าไหนทำกำไรสูงสุด สินค้าไหนค้างสต็อกขายช้า ช่วยให้ตัดสินใจสั่งสินค้าได้แม่นยำ',
    'ຈັດການກະພະນັກງານ ແລະ ລັອກການທຸຈະລິດ' => 'จัดการกะพนักงานและป้องกันการทุจริต',
    'ແບ່ງກະການຂາຍ (Shift), ນັບເງິນສົດໃນລິ້ນຊັກກົງກັບຍອດຂາຍ, ລັອກສິດການແກ້ໄຂລາຄາ ແລະ ການຍົກເລີກບິນ ປ້ອງກັນເງິນຕົກເຮ່ຍ.' => 'แบ่งกะการขาย นับเงินสดในลิ้นชักให้ตรงยอดขาย ล็อกสิทธิ์แก้ไขราคาและยกเลิกบิล ป้องกันเงินรั่วไหล',
    'ຮອງຮັບສິນຄ້າຫຼາຍກວ່າ 50,000+ ລາຍການ ພ້ອມຮອງຮັບບາໂຄດສິນຄ້າທົ່ວໄປ' => 'รองรับสินค้า 50,000+ รายการ พร้อมบาร์โค้ดสินค้าทั่วไป',
    'ລະບົບພິມບາໂຄດສິນຄ້າສຳລັບສິນຄ້າທີ່ບໍ່ມີບາໂຄດມາຈາກໂຮງງານ' => 'ระบบพิมพ์บาร์โค้ดสำหรับสินค้าที่ไม่มีบาร์โค้ดจากโรงงาน',
    'ຮອງຮັບການຂາຍຍົກແພັກ, ຂາຍຍົກລັງ ແລະ ຂາຍຍ່ອຍ (ຕັດສະຕັອກອັດຕະໂນມັດ)' => 'รองรับขายยกแพ็ก ยกลัง และขายปลีก (ตัดสต็อกอัตโนมัติ)',
    'ລະບົບໂປຣໂມຊັ່ນ: ຊື້ 1 ແຖມ 1, ສ່ວນຫຼຸດຕາມຊ່ວງເວລາ, ສະສົມຄະແນນສະມາຊິກ' => 'ระบบโปรโมชั่น: ซื้อ 1 แถม 1 ส่วนลดตามช่วงเวลา สะสมคะแนนสมาชิก',
    'ເຊື່ອມຕໍ່ລິ້ນຊັກເກັບເງິນ, ເຄື່ອງຍິງບາໂຄດ, ຈໍສະແດງລາຄາລູກຄ້າ ແລະ ປິ້ນເຕີບິນ' => 'เชื่อมต่อลิ้นชักเก็บเงิน เครื่องสแกนบาร์โค้ด จอแสดงราคาลูกค้า และเครื่องพิมพ์ใบเสร็จ',
    'ຕິດຕາມຍອດຂາຍຜ່ານ Dashboard ໃນມືຖືໄດ້ທຸກທີ່ ຕະຫຼອດ 24 ຊົ່ວໂມງ' => 'ติดตามยอดขายผ่าน Dashboard บนมือถือได้ทุกที่ 24 ชั่วโมง',
    'ລະບົບ POS ຮ້ານຂາຍຢາ ຈັດການລາຍການຢາ, ສະຕັອກ, ວັນໝົດອາຍຸ ແລະ ລາຍງານກຳໄລ' => 'ระบบ POS ร้านขายยา จัดการรายการยา สต็อก วันหมดอายุ และรายงานกำไร',
    'ລະບົບ POS ຮ້ານຂາຍຢາ ອອກແບບມາສະເພາະສຳລັບຮ້ານຂາຍຢາ ແລະ ຄລີນິກ: ຄຸ້ມຄອງວັນໝົດອາຍຸ (Exp Date), ຄົ້ນຫາຢາຕາມຊື່ການຄ້າ ແລະ ຊື່ສາມັນ, ຕັດສະຕັອກຫຼາຍໜ່ວຍ (ເມັດ/ແຜງ/ກ່ອງ), ພິມສະຫຼາກຢາພາສາລາວ, ແລະ ລາຍງານກຳໄລ-ຂາດທຶນ.' => 'ระบบ POS สำหรับร้านขายยาและคลินิก: ควบคุมวันหมดอายุ ค้นหายาตามชื่อการค้าและชื่อสามัญ ตัดสต็อกหลายหน่วย (เม็ด/แผง/กล่อง) พิมพ์ฉลากยาภาษาลาว และรายงานกำไร-ขาดทุน',
    'ໜ້າຈໍຂາຍຢາ ສະແດງສະຕັອກ, ວັນໝົດອາຍຸ ແລະ ໝວດໝູ່ຢາຊັດເຈນ' => 'หน้าจอขายยา แสดงสต็อก วันหมดอายุ และหมวดหมู่ยาชัดเจน',
    'ເຄື່ອງ POS Touchscreen ໜ້າຈໍໃຫຍ່ ສຳຜັດໄວ ສະອາດ ຖືກຫຼັກອະນາໄມ' => 'เครื่อง POS จอสัมผัสใหญ่ สัมผัสไว สะอาด ถูกหลักอนามัย',
    'ໂປຣແກຣມ POS ທັນສະໄໝ ຄຸ້ມຄອງສະຕັອກຢາ ແລະ ວັນໝົດອາຍຸ' => 'โปรแกรม POS ทันสมัย ควบคุมสต็อกยาและวันหมดอายุ',
    'ອຸປະກອນຄົບຊຸດ ພ້ອມເຄື່ອງພິມສະຫຼາກຢາ ແລະ ໃບບິນ' => 'อุปกรณ์ครบชุด พร้อมเครื่องพิมพ์ฉลากยาและใบเสร็จ',
    'ຄຸ້ມຄອງວັນໝົດອາຍຸ (Exp Date) & ລຸ້ນຜະລິດ (Lot)' => 'ควบคุมวันหมดอายุ (Exp Date) และล็อตผลิต (Lot)',
    'ແຈ້ງເຕືອນຢາໃກ້ໝົດອາຍຸລ່ວງໜ້າ (1, 3, 6 ເດືອນ) ປ້ອງກັນການຈ່າຍຢາໝົດອາຍຸໃຫ້ຄົນໄຂ້ ແລະ ຊ່ວຍວາງແຜນລະບາຍຢາໄດ້ທັນເວລາ.' => 'แจ้งเตือนยาใกล้หมดอายุล่วงหน้า (1, 3, 6 เดือน) ป้องกันการจ่ายยาหมดอายุ และช่วยวางแผนระบายยาได้ทันเวลา',
    'ຄົ້ນຫາຢາໄດ້ໄວ ທັງຊື່ການຄ້າ ແລະ ຊື່ສາມັນ' => 'ค้นหายาได้เร็ว ทั้งชื่อการค้าและชื่อสามัญ',
    'ຊອກຫາຢາໄດ້ງ່າຍດາຍຕາມຊື່ການຄ້າ, ຊື່ສາມັນທາງຢາ (Generic Name) ຫຼື ສັບພະຄຸນ ຊ່ວຍໃຫ້ເພດສັຊກອນຈ່າຍຢາໄດ້ຖືກຕ້ອງ ແລະ ວ່ອງໄວ.' => 'ค้นหายาได้ง่ายตามชื่อการค้า ชื่อสามัญ (Generic Name) หรือสรรพคุณ ช่วยให้เภสัชกรจ่ายยาได้ถูกต้องและรวดเร็ว',
    'ຕັດສະຕັອກຫຼາຍໜ່ວຍນັບ (ເມັດ / ແຜງ / ກ່ອງ)' => 'ตัดสต็อกหลายหน่วยนับ (เม็ด / แผง / กล่อง)',
    'ຂາຍຢາເປັນເມັດ, ເປັນແຜງ, ຫຼື ເປັນກ່ອງໃຫຍ່ ລະບົບຄຳນວນແລະຕັດສະຕັອກອັດຕະໂນມັດຢ່າງຖືກຕ້ອງ ບໍ່ມີບັນຫາສະຕັອກຜິດພາດ.' => 'ขายยาเป็นเม็ด เป็นแผง หรือเป็นกล่อง ระบบคำนวณและตัดสต็อกอัตโนมัติอย่างถูกต้อง ไม่มีปัญหาสต็อกผิดพลาด',
    'ພິມສະຫຼາກຢາ ແລະ ວິທີໃຊ້ຢາພາສາລາວ' => 'พิมพ์ฉลากยาและวิธีใช้ยาภาษาลาว',
    'ອອກສະຫຼາກວິທີໃຊ້ຢາ (ກິນກ່ອນ/ຫຼັງອາຫານ, ເຊົ້າ-ສວາຍ-ແລງ-ກ່ອນນອນ) ຕິດຊອງຢາໄດ້ທັນທີ ເພີ່ມຄວາມໜ້າເຊື່ອຖື ແລະ ຄວາມປອດໄພ.' => 'ออกฉลากวิธีใช้ยา (ก่อน/หลังอาหาร เช้า-กลางวัน-เย็น-ก่อนนอน) ติดซองยาได้ทันที เพิ่มความน่าเชื่อถือและความปลอดภัย',
    'ບັນທຶກປະຫວັດຄົນໄຂ້ ແລະ ລາຍງານກຳໄລ-ຂາດທຶນ' => 'บันทึกประวัติผู้ป่วยและรายงานกำไร-ขาดทุน',
    'ບັນທຶກປະຫວັດການແພ້ຢາ ແລະ ປະຫວັດການຊື້ຂອງຄົນໄຂ້ ພ້ອມສະຫຼຸບລາຍຮັບ, ຕົ້ນທຶນ ແລະ ກຳໄລສຸດທິຢ່າງລະອຽດ.' => 'บันทึกประวัติแพ้ยาและประวัติการซื้อของผู้ป่วย พร้อมสรุปรายรับ ต้นทุน และกำไรสุทธิอย่างละเอียด',
    'ລະບົບແຈ້ງເຕືອນຢາໃກ້ໝົດອາຍຸ ແລະ ຢາໃກ້ໝົດສະຕັອກອັດຕະໂນມັດ' => 'แจ้งเตือนยาใกล้หมดอายุและยาใกล้หมดสต็อกอัตโนมัติ',
    'ຮອງຮັບການຂາຍຢາແຍກໜ່ວຍ: ເມັດ, ແຜງ, ຂວດ, ຫຼອດ, ກ່ອງ' => 'รองรับการขายยาแยกหน่วย: เม็ด แผง ขวด หลอด กล่อง',
    'ບັນທຶກເລກທະບຽນຢາ, ລຸ້ນຜະລິດ (Lot Number) ແລະ ຜູ້ສະໜອງຢາ' => 'บันทึกเลขทะเบียนยา ล็อตผลิต (Lot Number) และผู้จำหน่ายยา',
    'ພິມສະຫຼາກຢາພາສາລາວຕິດຊອງຢາ ພ້ອມຊື່ຄົນໄຂ້ ແລະ ຄຳເຕືອນການໃຊ້' => 'พิมพ์ฉลากยาภาษาลาวติดซองยา พร้อมชื่อผู้ป่วยและคำเตือน',
    'ຮອງຮັບການສະແກນບາໂຄດຢາ ແລະ ຄົ້ນຫາດ້ວຍຄີເວີດສັບພະຄຸນ' => 'รองรับสแกนบาร์โค้ดยาและค้นหาด้วยคำสำคัญสรรพคุณ',
    'ລາຍງານການຂາຍຢາຄວບຄຸມພິເສດ ແລະ ສະຫຼຸບຍອດຂາຍປະຈຳວັນ' => 'รายงานการขายยาควบคุมพิเศษและสรุปยอดขายรายวัน',
    'ລະບົບຂາຍໜ້າຮ້ານຄົບວົງຈອນ ສຳລັບຮ້ານຂາຍຍ່ອຍ, ໂຊຫ່ວຍ, ແລະ ຮ້ານຄ້າທົ່ວໄປ' => 'ระบบขายหน้าร้านครบวงจร สำหรับร้านค้าปลีก โชห่วย และร้านค้าทั่วไป',
    'ລະບົບ POS ຮ້ານຂາຍຍ່ອຍ ຕອບໂຈດທຸລະກິດການຄ້າຂາຍທຸກຂະໜາດ: ຄິດເງິນໄວ, ຍິງບາໂຄດແມ່ນຍຳ, ອອກໃບບິນງາມ, ຕັດສະຕັອກ Real-time, ຈັດການລູກຄ້າປະຈຳ, ແລະ ເບິ່ງຍອດຂາຍຜ່ານມືຖືໄດ້ທຸກບ່ອນ.' => 'ระบบ POS ร้านค้าปลีก ตอบโจทย์ทุกขนาด: คิดเงินเร็ว สแกนบาร์โค้ดแม่นยำ ใบเสร็จสวย ตัดสต็อก Real-time จัดการลูกค้าประจำ และดูยอดขายผ่านมือถือได้ทุกที่',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານຂາຍຍ່ອຍ ຄົບວົງຈອນ ໃຊ້ງານງ່າຍ' => 'หน้าจอขายร้านค้าปลีก ครบวงจร ใช้งานง่าย',
    'ເຄົາເຕີ້ຄິດເງິນຮ້ານຂາຍຍ່ອຍ ພ້ອມເຄື່ອງຍິງບາໂຄດ ແລະ ລິ້ນຊັກເກັບເງິນ' => 'เคาน์เตอร์คิดเงินร้านค้าปลีก พร้อมเครื่องสแกนบาร์โค้ดและลิ้นชักเก็บเงิน',
    'ຄິດເງິນໄວ ຫຼຸດຄວາມຜິດພາດໃນການຂາຍ 100%' => 'คิดเงินเร็ว ลดความผิดพลาดในการขาย',
    'ຍິງບາໂຄດ ຄິດເງິນ ແລະ ທອນເງິນຢ່າງຖືກຕ້ອງ ບໍ່ຕ້ອງເສຍເວລາກົດເຄື່ອງຄິດເລກ ຫຼຸດການຕົກຫຼົ່ນຂອງຍອດຂາຍ.' => 'สแกนบาร์โค้ด คิดเงิน และทอนเงินอย่างถูกต้อง ไม่ต้องกดเครื่องคิดเลข ลดยอดขายตกหล่น',
    'ຄຸ້ມຄອງສາງສິນຄ້າ & ຕັດສະຕັອກອັດຕະໂນມັດ' => 'จัดการคลังสินค้าและตัดสต็อกอัตโนมัติ',
    'ຮູ້ຍອດສິນຄ້າເຫຼືອໃນຮ້ານທັນທີ ບໍ່ຕ້ອງນັ່ງນັບສະຕັອກທຸກມື້, ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດສະຕັອກ ປ້ອງກັນສິນຄ້າຂາດຮ້ານ.' => 'รู้ยอดสินค้าคงเหลือทันที ไม่ต้องนั่งนับสต็อกทุกวัน แจ้งเตือนสินค้าใกล้หมด ป้องกันสินค้าขาดร้าน',
    'ປ້ອງກັນເງິນຕົກເຮ່ຍ ແລະ ກວດສອບຍອດຂາຍໄດ້ທຸກເວລາ' => 'ป้องกันเงินรั่วไหลและตรวจสอบยอดขายได้ทุกเวลา',
    'ບັນທຶກທຸກຍອດຂາຍຢ່າງລະອຽດ, ເປີດລິ້ນຊັກເກັບເງິນສະເພາະຕອນພິມບິນ, ກວດຍອດຂາຍໄດ້ຕະຫຼອດ.' => 'บันทึกทุกยอดขายอย่างละเอียด เปิดลิ้นชักเฉพาะตอนพิมพ์บิล ตรวจยอดขายได้ตลอด',
    'ຕິດຕາມຍອດຂາຍໄດ້ທຸກທີ່ຜ່ານມືຖື ຕະຫຼອດ 24 ຊົ່ວໂມງ' => 'ติดตามยอดขายได้ทุกที่ผ่านมือถือ 24 ชั่วโมง',
    'ເບິ່ງຍອດຂາຍປະຈຳວັນ, ກຳໄລສຸດທິ ແລະ ລາຍການສິນຄ້າຂາຍດີຜ່ານໂທລະສັບມືຖື ຢູ່ໃສກໍສາມາດບໍລິຫານຮ້ານໄດ້.' => 'ดูยอดขายรายวัน กำไรสุทธิ และสินค้าขายดีผ่านมือถือ อยู่ที่ไหนก็บริหารร้านได้',
    'ລະບົບສະມາຊິກ & ສະສົມແຕ້ມ ດຶງດູດລູກຄ້າກັບມາຊື້ຊ້ຳ' => 'ระบบสมาชิกและสะสมแต้ม ดึงดูดลูกค้ากลับมาซื้อซ้ำ',
    'ບັນທຶກເບີໂທລູກຄ້າ, ໃຫ້ຄະແນນສະສົມ, ມອບສ່ວນຫຼຸດພິເສດສຳລັບລູກຄ້າປະຈຳ ເພີ່ມຍອດຂາຍໃຫ້ຮ້ານຢ່າງຍືນຍົງ.' => 'บันทึกเบอร์โทรลูกค้า ให้คะแนนสะสม มอบส่วนลดพิเศษให้ลูกค้าประจำ เพิ่มยอดขายอย่างยั่งยืน',
    'ຮອງຮັບການສະແກນບາໂຄດທັງ 1D ແລະ 2D ວ່ອງໄວ' => 'รองรับสแกนบาร์โค้ดทั้ง 1D และ 2D อย่างรวดเร็ว',
    'ຮອງຮັບຫຼາຍສະກຸນເງິນ: ກີບ (LAK), ບາດ (THB), ໂດລາ (USD), ຢວນ (CNY)' => 'รองรับหลายสกุลเงิน: กีบ (LAK) บาท (THB) ดอลลาร์ (USD) หยวน (CNY)',
    'ພິມໃບບິນຮັບເງິນພາສາລາວ ພ້ອມໂລໂກ້ຮ້ານຄ້າ' => 'พิมพ์ใบเสร็จรับเงินภาษาลาวพร้อมโลโก้ร้าน',
    'ລະບົບສະມາຊິກ, ສະສົມແຕ້ມ, ແລະ ສ່ວນຫຼຸດໂປຣໂມຊັ່ນ' => 'ระบบสมาชิก สะสมแต้ม และส่วนลดโปรโมชั่น',
    'ຈັດການຫຼາຍສາຂາ ແລະ ໂອນຍ້າຍສິນຄ້າລະຫວ່າງສາຂາ' => 'จัดการหลายสาขาและโอนย้ายสินค้าระหว่างสาขา',
    'ລາຍງານສະຫຼຸບຍອດຂາຍ, ຍອດກຳໄລ, ແລະ ຍອດສິນຄ້າຄົງເຫຼືອແບບ Real-time' => 'รายงานสรุปยอดขาย กำไร และสินค้าคงเหลือแบบ Real-time',
    'ລະບົບ POS ຮ້ານອາຫານ ຄົບວົງຈອນ: ຈັດການໂຕະ, ສົ່ງອໍເດີເຂົ້າຄົວ, ແຍກບິນ ແລະ ຕັດສະຕັອກ' => 'ระบบ POS ร้านอาหารครบวงจร: จัดการโต๊ะ ส่งออเดอร์เข้าครัว แยกบิล และตัดสต็อก',
    'ລະບົບ POS ຮ້ານອາຫານ ອອກແບບມາເພື່ອຮອງຮັບຮ້ານອາຫານຂະໜາດນ້ອຍເຖິງໃຫຍ່: ແຜນຜັງໂຕະສະເໝືອນຈິງ, ສັ່ງອາຫານຜ່ານແທັບເລັດ/ມືຖື, ສົ່ງອໍເດີເຂົ້າຄົວອັດຕະໂນມັດ, ແຍກບິນ/ລວມບິນ, ຕັດສະຕັອກວັດຖຸດິບ, ແລະ ລາຍງານຍອດຂາຍ Real-time.' => 'ระบบ POS ร้านอาหารสำหรับร้านขนาดเล็กถึงใหญ่: ผังโต๊ะเสมือนจริง สั่งอาหารผ่านแท็บเล็ต/มือถือ ส่งออเดอร์เข้าครัวอัตโนมัติ แยก/รวมบิล และรายงานยอดขาย Real-time',
    'ໜ້າຈໍລະບົບ POS ຮ້ານອາຫານ ສຳຜັດງ່າຍ ເມນູພາບງາມ ຈັດການໂຕະ' => 'หน้าจอระบบ POS ร้านอาหาร สัมผัสง่าย เมนูรูปสวย จัดการโต๊ะ',
    'ເຄື່ອງ POS Dual Screen Touchscreen ຄົບຊຸດພ້ອມລິ້ນຊັກ ແລະ ປິ້ນເຕີບິນ' => 'เครื่อง POS จอสัมผัส Dual Screen ครบชุด พร้อมลิ้นชักและเครื่องพิมพ์ใบเสร็จ',
    'ລະບົບຄິດເງິນ ແລະ ພິມໃບສັ່ງອາຫານເຂົ້າຄົວ (Kitchen Printer)' => 'ระบบคิดเงินและพิมพ์ใบสั่งอาหารเข้าครัว (Kitchen Printer)',
    'ບັນຍາກາດການໃຊ້ງານໃນຮ້ານອາຫານ ຈັດການໂຕະ ແລະ ອໍເດີ' => 'บรรยากาศการใช้งานในร้านอาหาร จัดการโต๊ะและออเดอร์',
    'ສົ່ງອໍເດີເຂົ້າຄົວທັນທີ ຫຼຸດເວລາລໍຖ້າອາຫານ 50%' => 'ส่งออเดอร์เข้าครัวทันที ลดเวลารออาหาร 50%',
    'ເມື່ອກົດສັ່ງ, ລາຍການອາຫານຈະຖືກພິມອອກທີ່ຄົວ ແລະ ບາຣ໌ນ້ຳທັນທີ ພໍ່ຄົວປຸງອາຫານໄດ້ຕໍ່ເນື່ອງ ບໍ່ມີອໍເດີຕົກຫຼົ່ນ.' => 'เมื่อกดสั่ง รายการอาหารจะพิมพ์ออกที่ครัวและบาร์น้ำทันที พ่อครัวทำอาหารได้ต่อเนื่อง ไม่มีออเดอร์ตกหล่น',
    'ຈັດການແຜນຜັງໂຕະ, ຍ້າຍໂຕະ ແລະ ລວມໂຕະງ່າຍດາຍ' => 'จัดการผังโต๊ะ ย้ายโต๊ะ และรวมโต๊ะง่าย',
    'ເບິ່ງສະຖານະໂຕະວ່າງ/ບໍ່ວ່າງໄດ້ທັນທີ, ຮອງຮັບການຍ້າຍໂຕະ, ລວມໂຕະ, ແລະ ແຍກບິນຕາມກຸ່ມລູກຄ້າ.' => 'ดูสถานะโต๊ะว่าง/ไม่ว่างได้ทันที รองรับย้ายโต๊ะ รวมโต๊ะ และแยกบิลตามกลุ่มลูกค้า',
    'ພັກບິນໄວ້ ສັ່ງເພີ່ມໄດ້ຈົນກວ່າຈະຊຳລະ' => 'พักบิลไว้ สั่งเพิ่มได้จนกว่าจะชำระ',
    'ບິນຂອງແຕ່ລະໂຕະຖືກບັນທຶກໄວ້ໃນລະບົບ ລູກຄ້າສັ່ງເພີ່ມເທື່ອໃດກໍ່ໄດ້ ບໍ່ຫາຍ ເຖິງວ່າຈະປິດເຄື່ອງ.' => 'บิลของแต่ละโต๊ะถูกบันทึกไว้ในระบบ ลูกค้าสั่งเพิ่มเมื่อไหร่ก็ได้ ไม่หาย แม้ปิดเครื่อง',
    'ຕິດຕາມຍອດຂາຍ ແລະ ໂຕະທີ່ກຳລັງກິນຜ່ານມືຖື' => 'ติดตามยอดขายและโต๊ะที่กำลังทานผ่านมือถือ',
    'ເຈົ້າຂອງຮ້ານກວດເບິ່ງຍອດຂາຍ, ຍອດບິນ, ແລະ ລາຍການອາຫານຂາຍດີຜ່ານໂທລະສັບມືຖືໄດ້ຕະຫຼອດ 24 ຊົ່ວໂມງ.' => 'เจ้าของร้านตรวจดูยอดขาย ยอดบิล และเมนูขายดีผ่านมือถือได้ตลอด 24 ชั่วโมง',
    'ປ້ອງກັນເງິນຕົກເຮ່ຍ & ຄຸ້ມຄອງພະນັກງານເສີບ' => 'ป้องกันเงินรั่วไหลและควบคุมพนักงานเสิร์ฟ',
    'ແຍກສິດພະນັກງານ (ພະນັກງານເສີບ, ແຄັດເຊຍ, ຜູ້ຈັດການ), ລັອກສິດການຍົກເລີກອາຫານ, ແລະ ກວດສອບຍອດເງິນໂປ່ງໃສ.' => 'แยกสิทธิ์พนักงาน (พนักงานเสิร์ฟ แคชเชียร์ ผู้จัดการ) ล็อกสิทธิ์ยกเลิกอาหาร และตรวจสอบยอดเงินโปร่งใส',
    'ແຜນຜັງໂຕະສະເໝືອນຈິງ ແບ່ງໂຊນ Indoor, Outdoor, VIP' => 'ผังโต๊ะเสมือนจริง แบ่งโซน Indoor, Outdoor, VIP',
    'ຮອງຮັບການສັ່ງອາຫານຜ່ານແທັບເລັດ ຫຼື ມືຖືຂອງພະນັກງານເສີບ' => 'รองรับสั่งอาหารผ่านแท็บเล็ตหรือมือถือของพนักงานเสิร์ฟ',
    'ພິມໃບສັ່ງແຍກຄົວ (ຄົວຕົ້ມ, ຄົວປີ້ງ, ບາຣ໌ນ້ຳ) ອັດຕະໂນມັດ' => 'พิมพ์ใบสั่งแยกครัว (ครัวต้ม ครัวปิ้ง บาร์น้ำ) อัตโนมัติ',
    'ຮອງຮັບການແຍກບິນ, ລວມບິນ, ແລະ ໃສ່ສ່ວນຫຼຸດ (VIP, ວັນເກີດ)' => 'รองรับแยกบิล รวมบิล และใส่ส่วนลด (VIP, วันเกิด)',
    'ສະຫຼຸບຍອດຂາຍປະຈຳວັນ, ປິດກະການຂາຍ, ແລະ ລາຍງານຍອດນິຍົມ' => 'สรุปยอดขายรายวัน ปิดกะ และรายงานเมนูยอดนิยม',
    '%s ຄຸນນະພາບສູງ ພ້ອມຕິດຕັ້ງ ແລະ ເຊື່ອມຕໍ່ລະບົບ POS ທັນທີ' => '%s คุณภาพสูง พร้อมติดตั้งและเชื่อมต่อระบบ POS ทันที',
    '%s ອຸປະກອນມາດຕະຖານສຳລັບຮ້ານຄ້າ ແລະ ທຸລະກິດທຸກຂະໜາດ ທົນທານ ໃຊ້ງານງ່າຍ ຮອງຮັບການເຊື່ອມຕໍ່ກັບລະບົບຂາຍໜ້າຮ້ານ POS ພ້ອມບໍລິການຕິດຕັ້ງ ແລະ ຮັບປະກັນໂດຍທີມງານມືອາຊີບ.' => '%s อุปกรณ์มาตรฐานสำหรับร้านค้าและธุรกิจทุกขนาด ทนทาน ใช้งานง่าย เชื่อมต่อระบบ POS ได้ พร้อมบริการติดตั้งและรับประกันโดยทีมงานมืออาชีพ',
    'ອຸປະກອນ POS ຄົບຊຸດ ພ້ອມໃຊ້ງານ' => 'อุปกรณ์ POS ครบชุด พร้อมใช้งาน',
    'ເຮັດວຽກວ່ອງໄວ ແມ່ນຍຳ ທົນທານຕໍ່ການໃຊ້ງານໜັກ' => 'ทำงานเร็ว แม่นยำ ทนทานต่อการใช้งานหนัก',
    'ອຸປະກອນຄຸນນະພາບມາດຕະຖານ ຮອງຮັບການເຮັດວຽກຕໍ່ເນື່ອງໜ້າຮ້ານທັງວັນ.' => 'อุปกรณ์คุณภาพมาตรฐาน รองรับการทำงานต่อเนื่องหน้าร้านทั้งวัน',
    'ເຊື່ອມຕໍ່ລະບົບ POS ໄດ້ທັນທີ (Plug & Play)' => 'เชื่อมต่อระบบ POS ได้ทันที (Plug & Play)',
    'ຮອງຮັບການເຊື່ອມຕໍ່ USB / LAN / Bluetooth ເຂົ້າກັບຄອມພິວເຕີ ແລະ ເຄື່ອງ POS.' => 'รองรับเชื่อมต่อ USB / LAN / Bluetooth กับคอมพิวเตอร์และเครื่อง POS',
    'ຕິດຕັ້ງຟຣີ ພ້ອມສອນການໃຊ້ງານ ແລະ ຮັບປະກັນ' => 'ติดตั้งฟรี พร้อมสอนใช้งานและรับประกัน',
    'ທີມງານຕັ້ງຄ່າ ທົດສອບລະບົບໃຫ້ພ້ອມໃຊ້ງານ ແລະ ດູແລຫຼັງການຂາຍຕະຫຼອດອາຍຸການໃຊ້ງານ.' => 'ทีมงานตั้งค่า ทดสอบระบบให้พร้อมใช้งาน และดูแลหลังการขายตลอดอายุการใช้งาน',
    'ວັດສະດຸແຂງແຮງ ທົນທານ ອອກແບບມາສຳລັບວຽກຂາຍໜ້າຮ້ານໂດຍສະເພາະ' => 'วัสดุแข็งแรง ทนทาน ออกแบบมาสำหรับงานขายหน้าร้านโดยเฉพาะ',
    'ເຊື່ອມຕໍ່ເຂົ້າກັບໂປຣແກຣມ POS ໄດ້ທຸກຮູບແບບ' => 'เชื่อมต่อกับโปรแกรม POS ได้ทุกรูปแบบ',
    'ຮອງຮັບການພິມ/ສະແກນ ຫຼື ໃຊ້ງານຮ່ວມກັບພາສາລາວຢ່າງສົມບູນ' => 'รองรับการพิมพ์/สแกน หรือใช้งานร่วมกับภาษาลาวอย่างสมบูรณ์',
    'ຕິດຕັ້ງ ແລະ ຕັ້ງຄ່າໃຫ້ພ້ອມໃຊ້ງານໂດຍທີມງານ WlaoDev' => 'ติดตั้งและตั้งค่าพร้อมใช้งานโดยทีมงาน WlaoDev',
    'ມີບໍລິການຫຼັງການຂາຍ ແລະ ອະໄຫຼ່ຮອງຮັບຄົບຖ້ວນ' => 'มีบริการหลังการขายและอะไหล่รองรับครบถ้วน',
    'ລະບົບຂາຍໜ້າຮ້ານ POS ຄົບວົງຈອນ ຕອບໂຈດທຸລະກິດຂອງທ່ານ' => 'ระบบขายหน้าร้าน POS ครบวงจร ตอบโจทย์ธุรกิจของคุณ',
    'ລະບົບ POS %s ອອກແບບມາເພື່ອຊ່ວຍໃຫ້ທຸລະກິດຂອງທ່ານດຳເນີນງານຢ່າງມີປະສິດທິພາບສູງສຸດ: ຂາຍໜ້າຮ້ານໄວ, ຕັດສະຕັອກອັດຕະໂນມັດ, ປ້ອງກັນເງິນຕົກເຮ່ຍ, ພິມໃບບິນພາສາລາວ, ແລະ ເບິ່ງຍອດຂາຍຜ່ານມືຖືໄດ້ທຸກບ່ອນ.' => 'ระบบ POS %s ออกแบบมาเพื่อให้ธุรกิจของคุณทำงานอย่างมีประสิทธิภาพ: ขายเร็ว ตัดสต็อกอัตโนมัติ ป้องกันเงินรั่วไหล พิมพ์ใบเสร็จภาษาลาว และดูยอดขายผ่านมือถือได้ทุกที่',
    'ເຄື່ອງ POS Dual Screen Touchscreen ແລະ ອຸປະກອນຄົບຊຸດ' => 'เครื่อง POS จอสัมผัส Dual Screen และอุปกรณ์ครบชุด',
    'ໂປຣແກຣມ POS ທັນສະໄໝ ຮອງຮັບ Smart Touch' => 'โปรแกรม POS ทันสมัย รองรับ Smart Touch',
    'ລະບົບຄິດເງິນ ແລະ ຊຳລະສະດວກທຸກຮູບແບບ' => 'ระบบคิดเงินและชำระได้ทุกรูปแบบ',
    'ບໍລິການລູກຄ້າໄວຂຶ້ນ ແລະ ຫຼຸດຄວາມຜິດພາດ 100%' => 'บริการลูกค้าเร็วขึ้นและลดความผิดพลาด',
    'ລະບົບຊ່ວຍໃຫ້ຄິດເງິນ ອອກໃບບິນ ແລະ ຕັດສະຕັອກໄດ້ໄວ ຫຼຸດເວລາລໍຖ້າຂອງລູກຄ້າ ແລະ ບໍ່ມີຍອດຂາຍຕົກຫຼົ່ນ.' => 'ระบบช่วยให้คิดเงิน ออกใบเสร็จ และตัดสต็อกได้เร็ว ลดเวลารอของลูกค้า และไม่มียอดขายตกหล่น',
    'ຕັດສະຕັອກ Real-time ຮູ້ຍອດສິນຄ້າເຫຼືອທັນທີ' => 'ตัดสต็อก Real-time รู้ยอดสินค้าคงเหลือทันที',
    'ຕັດສະຕັອກທຸກຄັ້ງທີ່ຂາຍ ແຈ້ງເຕືອນສິນຄ້າໃກ້ໝົດ ປ້ອງກັນສິນຄ້າຂາດຮ້ານ ແລະ ສິນຄ້າສູນຫາຍ.' => 'ตัดสต็อกทุกครั้งที่ขาย แจ้งเตือนสินค้าใกล้หมด ป้องกันสินค้าขาดร้านและสูญหาย',
    'ບັນທຶກທຸກຍອດຂາຍຢ່າງລະອຽດ, ແຍກກະການຂາຍ, ລັອກສິດການຍົກເລີກບິນ ປ້ອງກັນການທຸຈະລິດ.' => 'บันทึกทุกยอดขายอย่างละเอียด แยกกะการขาย ล็อกสิทธิ์ยกเลิกบิล ป้องกันการทุจริต',
    'ຕິດຕາມຍອດຂາຍ ແລະ ກຳໄລໄດ້ທຸກທີ່ຜ່ານມືຖື' => 'ติดตามยอดขายและกำไรได้ทุกที่ผ่านมือถือ',
    'ເຈົ້າຂອງທຸລະກິດເບິ່ງຍອດຂາຍ, ຕົ້ນທຶນ ແລະ ກຳໄລສຸດທິຜ່ານມືຖືໄດ້ຕະຫຼອດ 24 ຊົ່ວໂມງ ບໍ່ຈຳເປັນຕ້ອງຢູ່ຮ້ານ.' => 'เจ้าของธุรกิจดูยอดขาย ต้นทุน และกำไรสุทธิผ่านมือถือได้ตลอด 24 ชั่วโมง ไม่จำเป็นต้องอยู่ร้าน',
    'ໜ້າຈໍຂາຍໜ້າຮ້ານສຳຜັດງ່າຍ ເມນູພາບງາມ ໃຊ້ງານເປັນພາຍໃນ 5 ນາທີ' => 'หน้าจอขายแบบสัมผัสง่าย เมนูรูปสวย ใช้งานเป็นภายใน 5 นาที',
    'ຮອງຮັບການພິມໃບບິນພາສາລາວ ພ້ອມໂລໂກ້ຮ້ານຄ້າ' => 'รองรับการพิมพ์ใบเสร็จภาษาลาวพร้อมโลโก้ร้าน',
    'ເຊື່ອມຕໍ່ອຸປະກອນ: ປິ້ນເຕີບິນ, ເຄື່ອງຍິງບາໂຄດ, ລິ້ນຊັກເກັບເງິນ' => 'เชื่อมต่ออุปกรณ์: เครื่องพิมพ์ใบเสร็จ เครื่องสแกนบาร์โค้ด ลิ้นชักเก็บเงิน',
    'ລາຍງານຍອດຂາຍ ແລະ ກຳໄລ Real-time ຜ່ານມືຖື' => 'รายงานยอดขายและกำไร Real-time ผ่านมือถือ',
    'ເຮັດວຽກໄດ້ທັງ Offline (ເນັດຫຼຸດຍັງຂາຍໄດ້) ແລະ Online' => 'ทำงานได้ทั้ง Offline (เน็ตหลุดยังขายได้) และ Online',
    'ລູກຄ້າຕໍ່ຄິວຍາວ ຮັບອໍເດີບໍ່ທັນ' => 'ลูกค้าต่อคิวยาว รับออเดอร์ไม่ทัน',
    'ສັ່ງນ້ຳຜິດ ລືມອໍເດີ ຕ້ອງຮ້ອງບອກກັນ' => 'สั่งน้ำผิด ลืมออเดอร์ ต้องตะโกนบอกกัน',
    'ຢາກຈັດໂປຣ ແຕ່ຄິດສ່ວນຫຼຸດດ້ວຍມື ຜິດ ແລະ ຊ້າ' => 'อยากจัดโปร แต่คิดส่วนลดด้วยมือ ผิดและช้า',
    'ຕ້ອງຢູ່ຮ້ານຕະຫຼອດ ຈຶ່ງຮູ້ຍອດຂາຍ' => 'ต้องอยู่ร้านตลอด ถึงจะรู้ยอดขาย',
    'ເງິນໃນລິ້ນຊັກບໍ່ກົງກັບຍອດຂາຍ' => 'เงินในลิ้นชักไม่ตรงกับยอดขาย',
    'ສິນຄ້າຫຼາຍ ຈື່ລາຄາບໍ່ໄດ້ ຄິດເງິນຊ້າ' => 'สินค้าเยอะ จำราคาไม่ได้ คิดเงินช้า',
    'ສິນຄ້າຫາຍ ບໍ່ຮູ້ວ່າເຫຼືອເທົ່າໃດ' => 'สินค้าหาย ไม่รู้ว่าเหลือเท่าไร',
    'ລູກຄ້າຈ່າຍເງິນບາດ, ໂດລາ ຄິດແລກປ່ຽນຍາກ' => 'ลูกค้าจ่ายเงินบาท ดอลลาร์ คิดแลกเปลี่ยนยาก',
    'ບໍ່ຮູ້ວ່າສິນຄ້າໃດຂາຍດີ ກຳໄລເທົ່າໃດ' => 'ไม่รู้ว่าสินค้าไหนขายดี กำไรเท่าไร',
    'ປ່ຽນກະແລ້ວເງິນຂາດ ບໍ່ຮູ້ວ່າຂາດຍ້ອນໃຜ' => 'เปลี่ยนกะแล้วเงินขาด ไม่รู้ว่าขาดเพราะใคร',
    'ຢາໝົດອາຍຸຄ້າງຮ້ານ ບໍ່ຮູ້ຕົວ' => 'ยาหมดอายุค้างร้าน ไม่รู้ตัว',
    'ຊອກຢາຊ້າ ຈື່ຊື່ຢາບໍ່ໄດ້ໝົດ' => 'หายาช้า จำชื่อยาไม่ได้หมด',
    'ຂາຍເປັນເມັດ ເປັນແຜງ ນັບສະຕັອກສັບສົນ' => 'ขายเป็นเม็ด เป็นแผง นับสต็อกสับสน',
    'ຂຽນວິທີໃຊ້ຢາດ້ວຍມື ເສຍເວລາ ອ່ານຍາກ' => 'เขียนวิธีใช้ยาด้วยมือ เสียเวลา อ่านยาก',
    'ບໍ່ມີປະຫວັດລູກຄ້າ ບໍ່ຮູ້ກຳໄລແທ້' => 'ไม่มีประวัติลูกค้า ไม่รู้กำไรจริง',
    'ຄິດເງິນດ້ວຍມື ຊ້າ ແລະ ຜິດພາດ' => 'คิดเงินด้วยมือ ช้าและผิดพลาด',
    'ສິນຄ້າໃນສາງເຫຼືອເທົ່າໃດ ບໍ່ຮູ້' => 'สินค้าในคลังเหลือเท่าไร ไม่รู้',
    'ເງິນຕົກເຮ່ຍ ກວດສອບບໍ່ໄດ້' => 'เงินรั่วไหล ตรวจสอบไม่ได้',
    'ຢູ່ນອກຮ້ານ ບໍ່ຮູ້ວ່າຂາຍໄດ້ເທົ່າໃດ' => 'อยู่นอกร้าน ไม่รู้ว่าขายได้เท่าไร',
    'ລູກຄ້າຊື້ເທື່ອດຽວ ບໍ່ກັບມາອີກ' => 'ลูกค้าซื้อครั้งเดียว ไม่กลับมาอีก',
    'ອໍເດີຕົກຫຼົ່ນ ລູກຄ້າລໍຖ້າອາຫານດົນ' => 'ออเดอร์ตกหล่น ลูกค้ารออาหารนาน',
    'ໂຕະເຕັມ ສັບສົນ ບໍ່ຮູ້ໂຕະໃດວ່າງ' => 'โต๊ะเต็ม สับสน ไม่รู้โต๊ะไหนว่าง',
    'ລູກຄ້າສັ່ງເພີ່ມ ຈື່ບໍ່ໄດ້ວ່າໂຕະໃດສັ່ງຫຍັງ' => 'ลูกค้าสั่งเพิ่ม จำไม่ได้ว่าโต๊ะไหนสั่งอะไร',
    'ພະນັກງານຍົກເລີກອາຫານ ເງິນບໍ່ກົງ' => 'พนักงานยกเลิกอาหาร เงินไม่ตรง',
    'ລູກຄ້າລໍຖ້າດົນ ຄິດເງິນຜິດ' => 'ลูกค้ารอนาน คิดเงินผิด',
    'ສິນຄ້າໝົດ ຫຼື ຫາຍ ບໍ່ຮູ້ຕົວ' => 'สินค้าหมดหรือหาย ไม่รู้ตัว',
    'ພະນັກງານບໍ່ເກັ່ງຄອມ ຈະໃຊ້ເປັນບໍ?' => 'พนักงานไม่เก่งคอม จะใช้เป็นไหม?',
    'ໃຊ້ເປັນແນ່ນອນ — ໜ້າຈໍກົດງ່າຍຄືໃຊ້ມືຖື ທີມງານສອນເຖິງຮ້ານຈົນພະນັກງານຂາຍເອງໄດ້ ສ່ວນຫຼາຍໃຊ້ເປັນພາຍໃນມື້ດຽວ.' => 'ใช้เป็นแน่นอน — หน้าจอกดง่ายเหมือนใช้มือถือ ทีมงานสอนถึงร้านจนพนักงานขายเองได้ ส่วนใหญ่ใช้เป็นภายในวันเดียว',
    'ລະບົບມີບັນຫາຕອນກາງຄືນ ຫຼື ວັນພັກ ຕິດຕໍ່ໃຜ?' => 'ระบบมีปัญหาตอนกลางคืนหรือวันหยุด ติดต่อใคร?',
    'ໂທ ຫຼື WhatsApp ຫາທີມງານໄດ້ 24 ຊົ່ວໂມງ ທຸກມື້ — ແກ້ໄຂຜ່ານອອນລາຍທັນທີ ຖ້າຈຳເປັນຈະລົງໄປເຖິງຮ້ານ.' => 'โทรหรือ WhatsApp หาทีมงานได้ 24 ชั่วโมงทุกวัน — แก้ไขผ่านออนไลน์ทันที ถ้าจำเป็นจะไปถึงร้าน',
    'ຢາກເພີ່ມ ຫຼື ປ່ຽນຟັງຊັນໃຫ້ເໝາະກັບຮ້ານ ໄດ້ບໍ?' => 'อยากเพิ่มหรือเปลี่ยนฟังก์ชันให้เหมาะกับร้าน ได้ไหม?',
    'ໄດ້ — ພວກເຮົາພັດທະນາລະບົບເອງ ຈຶ່ງປັບແຕ່ງໃຫ້ຕາມຄວາມຕ້ອງການຂອງຮ້ານທ່ານໄດ້.' => 'ได้ — เราพัฒนาระบบเอง จึงปรับแต่งให้ตามความต้องการของร้านคุณได้',
    'ຖ້າອິນເຕີເນັດຫຼຸດ ລະບົບຍັງສາມາດຂາຍ ແລະ ອອກບິນໄດ້ບໍ່?' => 'ถ้าอินเทอร์เน็ตหลุด ระบบยังขายและออกบิลได้ไหม?',
    'ສາມາດຂາຍໄດ້ປົກກະຕິ 100%! ລະບົບຖືກອອກແບບມາໃຫ້ຮອງຮັບທັງແບບ Offline ແລະ Online ເມື່ອອິນເຕີເນັດກັບມາ ລະບົບຈະ Sync ຂໍ້ມູນຂຶ້ນຄລາວອັດຕະໂນມັດ.' => 'ขายได้ตามปกติ! ระบบรองรับทั้ง Offline และ Online เมื่ออินเทอร์เน็ตกลับมา ระบบจะ Sync ข้อมูลขึ้นคลาวด์อัตโนมัติ',
    'ມີທີມງານສອນການໃຊ້ງານ ແລະ ຕິດຕັ້ງໃຫ້ບໍ່?' => 'มีทีมงานสอนใช้งานและติดตั้งให้ไหม?',
    'ມີທີມງານຊ່ຽວຊານໄປຕິດຕັ້ງ ແລະ ສອນການໃຊ້ງານເຖິງສະຖານທີ່ຂອງທ່ານ (ຫຼື ຜ່ານອອນລາຍ) ພ້ອມຄູ່ມືພາສາລາວ ແລະ ວິດີໂອສອນທຸກຂັ້ນຕອນ.' => 'มีทีมผู้เชี่ยวชาญไปติดตั้งและสอนใช้งานถึงที่ (หรือผ่านออนไลน์) พร้อมคู่มือภาษาลาวและวิดีโอสอนทุกขั้นตอน',
    'ອຸປະກອນມີການຮັບປະກັນແນວໃດ?' => 'อุปกรณ์มีการรับประกันอย่างไร?',
    'ອຸປະກອນທຸກຊິ້ນຮັບປະກັນ 1 ປີເຕັມ. ຫາກມີບັນຫາທາງທີມງານມີເຄື່ອງສຳຮອງໃຫ້ໃຊ້ງານທັນທີ ເພື່ອບໍ່ໃຫ້ທຸລະກິດຂອງທ່ານສະດຸດ.' => 'อุปกรณ์ทุกชิ้นรับประกัน 1 ปีเต็ม หากมีปัญหา ทีมงานมีเครื่องสำรองให้ใช้ทันที เพื่อไม่ให้ธุรกิจสะดุด',
    'ສາມາດເບິ່ງຍອດຂາຍຜ່ານໂທລະສັບມືຖືໄດ້ບໍ່?' => 'ดูยอดขายผ่านมือถือได้ไหม?',
    'ໄດ້ແນ່ນອນ! ທ່ານສາມາດກວດເບິ່ງຍອດຂາຍ, ຍອດບິນ, ສິນຄ້າຂາຍດີ ແລະ ກຳໄລສຸດທິຜ່ານມືຖືໄດ້ທຸກບ່ອນ ຕະຫຼອດ 24 ຊົ່ວໂມງ.' => 'ได้แน่นอน! ตรวจดูยอดขาย ยอดบิล สินค้าขายดี และกำไรสุทธิผ่านมือถือได้ทุกที่ ตลอด 24 ชั่วโมง',
    'ສາມາດອອກໃບສະເໜີລາຄາ ແລະ ໃບຮັບເງິນໃນນາມບໍລິສັດໄດ້ບໍ່?' => 'ออกใบเสนอราคาและใบเสร็จในนามบริษัทได้ไหม?',
    'ໄດ້ຢ່າງແນ່ນອນ. ພວກເຮົາສາມາດອອກໃບສະເໜີລາຄາ (Quotation), ໃບຮຽກເກັບເງິນ (Invoice) ແລະ ໃບຮັບເງິນທີ່ຖືກຕ້ອງຕາມກົດໝາຍໃຫ້ອົງກອນ ແລະ ບໍລິສັດ.' => 'ได้แน่นอน เราออกใบเสนอราคา ใบแจ้งหนี้ และใบเสร็จที่ถูกต้องตามกฎหมายให้องค์กรและบริษัทได้',
    'ທີມພັດທະນາລະບົບ POS, ເວັບໄຊ ແລະ ແອັບມືຖື ທີ່ເຂົ້າໃຈທຸລະກິດລາວ' => 'ทีมพัฒนาระบบ POS เว็บไซต์ และแอปมือถือ ที่เข้าใจธุรกิจลาว',
    'ສະບາຍດີ ສົນໃຈປຶກສາລະບົບ' => 'สวัสดี สนใจปรึกษาระบบ',
    'ຊົ່ວໂມງ ດູແລຫຼັງການຂາຍ' => 'ชั่วโมง ดูแลหลังการขาย',
    'ພາສາລາວທຸກໜ້າຈໍ' => 'ภาษาลาวทุกหน้าจอ',
    'ໃບບິນ, ລາຍງານ ແລະ ເມນູເປັນພາສາລາວ ຮອງຮັບ 5 ພາສາ' => 'ใบเสร็จ รายงาน และเมนูเป็นภาษาลาว รองรับ 5 ภาษา',
    'ໃຊ້ໄດ້ທຸກອຸປະກອນ' => 'ใช้ได้ทุกอุปกรณ์',
    'ຄອມພິວເຕີ, ແທັບເລັດ ແລະ ມືຖື' => 'คอมพิวเตอร์ แท็บเล็ต และมือถือ',
    'ຫຼາຍສາຂາ ຫຼາຍສະກຸນເງິນ' => 'หลายสาขา หลายสกุลเงิน',
    'ເບິ່ງທຸກສາຂາໃນທີ່ດຽວ ກີບ, ບາດ, ໂດລາ' => 'ดูทุกสาขาในที่เดียว กีบ บาท ดอลลาร์',
    'ດູແລຈິງ ບໍ່ປະຖິ້ມ' => 'ดูแลจริง ไม่ทิ้ง',
    'ສອນໃຊ້ເຖິງຮ້ານ ມີບັນຫາແກ້ໃຫ້ທັນທີ 24 ຊົ່ວໂມງ' => 'สอนใช้ถึงร้าน มีปัญหาแก้ให้ทันที 24 ชั่วโมง',
    'ຟັງຄວາມຕ້ອງການຂອງທ່ານ' => 'รับฟังความต้องการของคุณ',
    'ພັດທະນາ & ຕິດຕັ້ງ' => 'พัฒนา & ติดตั้ง',
    'ເຮັດໃຫ້ຕາມທີ່ຕ້ອງການ' => 'ทำให้ตามที่ต้องการ',
    'ພວກເຮົາສ້າງລະບົບ ໃຫ້ທຸລະກິດລາວ ຂາຍງ່າຍຂຶ້ນ' => 'เราสร้างระบบ ให้ธุรกิจลาวขายง่ายขึ้น',
    '%s ພັດທະນາລະບົບ POS, ເວັບໄຊ ແລະ ແອັບມືຖື ເປັນພາສາລາວ ໃຊ້ງານງ່າຍ — ລູກຄ້າຕ້ອງການແນວໃດ ພວກເຮົາເຮັດໃຫ້ໄດ້.' => '%s พัฒนาระบบ POS เว็บไซต์ และแอปมือถือภาษาลาว ใช้งานง่าย — ลูกค้าต้องการแบบไหน เราทำให้ได้',
    'ເບິ່ງຜົນງານ →' => 'ดูผลงาน →',
    'ເບິ່ງບໍລິການ →' => 'ดูบริการ →',
