    'ພາສາລາວ' => 'ภาษาลาว',
    'ສິ່ງທີ່ພວກເຮົາເຮັດ' => 'สิ่งที่เราทำ',
    'ຈຸດເດັ່ນ' => 'จุดเด่น',
    'ພາລະກິດຂອງພວກເຮົາ' => 'พันธกิจของเรา',
    'ຊ່ວຍໃຫ້ທຸລະກິດລາວທຸກຂະໜາດ ໃຊ້ເຕັກໂນໂລຢີໄດ້ງ່າຍ ແລະ ເຕີບໂຕໄປພ້ອມກັນ' => 'ช่วยให้ธุรกิจลาวทุกขนาด ใช้เทคโนโลยีได้ง่าย และเติบโตไปพร้อมกัน',
    'ວິທີເຮັດວຽກກັບພວກເຮົາ' => 'วิธีทำงานกับเรา',
    'ສິດທິພິເສດ: ສ່ວນຫຼຸດສະມາຊິກ 5% ທຸກລາຍການ' => 'สิทธิพิเศษ: ส่วนลดสมาชิก 5% ทุกรายการ',
    'ລາຄາລວມ' => 'ราคารวม',
    'ສັ່ງຊື້ & ປ້ອນທີ່ຢູ່ຈັດສົ່ງ' => 'สั่งซื้อ & กรอกที่อยู่จัดส่ง',
    'ບໍ່ຢາກພິມ? ຕິດຕໍ່ທາງອື່ນໄດ້' => 'ไม่อยากพิมพ์? ติดต่อทางอื่นได้',
    'ສະບາຍດີ ສົນໃຈສອບຖາມ' => 'สวัสดี สนใจสอบถาม',
    'ປຶກສາຟຣີ ບໍ່ມີຄ່າໃຊ້ຈ່າຍ' => 'ปรึกษาฟรี ไม่มีค่าใช้จ่าย',
    'ຖາມໄດ້ທັນທີ ບໍ່ຕ້ອງລົງທະບຽນ' => 'ถามได้ทันที ไม่ต้องลงทะเบียน',
    'ດູແລຫຼັງການຂາຍ 24 ຊົ່ວໂມງ' => 'ดูแลหลังการขาย 24 ชั่วโมง',
    'ເວລາເປີດຮ້ານ' => 'เวลาเปิดร้าน',
    'ສະຖານທີ່ຕັ້ງ' => 'สถานที่ตั้ง',
    'ເປີດນຳທາງ / ເບິ່ງຮູບໃນ Google Maps' => 'เปิดนำทาง / ดูรูปใน Google Maps',
    'ບັນທຶກຂໍ້ມູນສັ່ງຊື້ສຳເລັດ' => 'บันทึกข้อมูลสั่งซื้อสำเร็จ',

    'ບັນທຶກຂໍ້ມູນທີ່ຢູ່ຈັດສົ່ງສຳເລັດ!' => 'บันทึกที่อยู่จัดส่งสำเร็จ!',
    'ກະລຸນາຕິດຕໍ່ທີມງານເພື່ອສອບຖາມລາຄາພິເສດ ແລະ ຊຳລະເງິນ — ເມື່ອໂອນເງິນແລ້ວ ພະນັກງານຫຼັງບ້ານຈະຈັດຝາກເຄື່ອງໃຫ້ຕາມຂໍ້ມູນລຸ່ມນີ້ທັນທີ.' => 'กรุณาติดต่อทีมงานเพื่อสอบถามราคาพิเศษและชำระเงิน — เมื่อโอนเงินแล้ว พนักงานจะจัดส่งสินค้าตามข้อมูลด้านล่างทันที',
    'ຜູ້ຮັບສິນຄ້າ:' => 'ผู้รับสินค้า:',
    'ທີ່ຢູ່ຈັດສົ່ງ:' => 'ที่อยู่จัดส่ง:',
    'ບໍລິສັດຂົນສົ່ງ:' => 'บริษัทขนส่ง:',
    'ສາຂາ:' => 'สาขา:',
    'ຍອດລວມທັງໝົດ' => 'ยอดรวมทั้งหมด',
    'ຕິດຕາມສະຖານະອໍເດີ' => 'ติดตามสถานะออเดอร์',
    'ຕິດຕໍ່ໂອນເງິນຜ່ານ WhatsApp' => 'ติดต่อโอนเงินผ่าน WhatsApp',
    'ເບິ່ງສິນຄ້າອື່ນຕໍ່' => 'ดูสินค้าอื่นต่อ',
    'ນະໂຍບາຍການເກັບກຳ, ນຳໃຊ້ ແລະ ປົກປ້ອງຂໍ້ມູນສ່ວນຕົວ ແລະ ຂໍ້ມູນທຸລະກິດຂອງລູກຄ້າ' => 'นโยบายการเก็บ ใช้ และปกป้องข้อมูลส่วนตัวและข้อมูลธุรกิจของลูกค้า',
    'ເງື່ອນໄຂການໃຫ້ບໍລິການລະບົບ POS, ອຸປະກອນ, ການຕິດຕັ້ງ ແລະ ການຮັບປະກັນຫຼັງການຂາຍ' => 'เงื่อนไขการให้บริการระบบ POS อุปกรณ์ การติดตั้ง และการรับประกันหลังการขาย',
    'ການເກັບກຳຂໍ້ມູນ' => 'การเก็บข้อมูล',
    'ພວກເຮົາໃຫ້ຄວາມສຳຄັນສູງສຸດຕໍ່ຄວາມປອດໄພຂອງຂໍ້ມູນລູກຄ້າ ແລະ ຂໍ້ມູນການຂາຍຂອງຮ້ານຄ້າ ໂດຍເກັບກຳສະເພາະຂໍ້ມູນທີ່ຈຳເປັນຕໍ່ການໃຫ້ບໍລິການ:' => 'เราให้ความสำคัญสูงสุดกับความปลอดภัยของข้อมูลลูกค้าและข้อมูลการขายของร้าน โดยเก็บเฉพาะข้อมูลที่จำเป็นต่อการให้บริการ:',
    'ຂໍ້ມູນການຕິດຕໍ່ ເຊັ່ນ: ຊື່-ນາມສະກຸນ, ຊື່ຮ້ານ/ບໍລິສັດ, ເບີໂທລະສັບ, WhatsApp, ອີເມວ ແລະ ທີ່ຢູ່ຈັດສົ່ງ ທີ່ລູກຄ້າແຈ້ງຜ່ານເວັບໄຊ.' => 'ข้อมูลการติดต่อ เช่น ชื่อ-นามสกุล ชื่อร้าน/บริษัท เบอร์โทร WhatsApp อีเมล และที่อยู่จัดส่ง ที่ลูกค้าแจ้งผ่านเว็บไซต์',
    'ຂໍ້ມູນລາຍລະອຽດການສັ່ງຊື້ອຸປະກອນ POS, ແພັກເກດລະບົບ ແລະ ປະຫວັດການຮັບບໍລິການຫຼັງການຂາຍ.' => 'รายละเอียดการสั่งซื้ออุปกรณ์ POS แพ็กเกจระบบ และประวัติการรับบริการหลังการขาย',
    'ວັດຖຸປະສົງການໃຊ້ຂໍ້ມູນ' => 'วัตถุประสงค์การใช้ข้อมูล',
    'ໃຊ້ເພື່ອຕິດຕໍ່ກັບ, ຢືນຢັນຄຳສັ່ງຊື້, ຈັດສົ່ງອຸປະກອນ ແລະ ນັດໝາຍຕິດຕັ້ງລະບົບ.' => 'ใช้เพื่อติดต่อกลับ ยืนยันคำสั่งซื้อ จัดส่งอุปกรณ์ และนัดหมายติดตั้งระบบ',
    'ໃຊ້ເພື່ອການດູແລຫຼັງການຂາຍ, ການອັບເດດລະບົບ ແລະ ການແກ້ໄຂບັນຫາດ້ານເຕັກນິກໃຫ້ແກ່ລູກຄ້າ.' => 'ใช้เพื่อดูแลหลังการขาย อัปเดตระบบ และแก้ไขปัญหาทางเทคนิคให้ลูกค้า',
    'ການຮັກສາຄວາມປອດໄພຂອງຂໍ້ມູນຮ້ານຄ້າ' => 'การรักษาความปลอดภัยของข้อมูลร้านค้า',
    'ຂໍ້ມູນສິນຄ້າ, ສະຕັອກ, ລາຍຊື່ລູກຄ້າ ແລະ ຍອດຂາຍໃນລະບົບ POS ຖືກເກັບຮັກສາເປັນຄວາມລັບສູງສຸດຂອງຮ້ານຄ້າ.' => 'ข้อมูลสินค้า สต็อก รายชื่อลูกค้า และยอดขายในระบบ POS ถูกเก็บเป็นความลับสูงสุดของร้าน',
    'ບໍ່ມີການເປີດເຜີຍ, ຈຳໜ່າຍ ຫຼື ສົ່ງຕໍ່ຂໍ້ມູນຂອງລູກຄ້າໃຫ້ບຸກຄົນທີສາມໂດຍບໍ່ໄດ້ຮັບອະນຸຍາດ.' => 'ไม่มีการเปิดเผย จำหน่าย หรือส่งต่อข้อมูลลูกค้าให้บุคคลที่สามโดยไม่ได้รับอนุญาต',
    'ສິດທິຂອງລູກຄ້າ ແລະ ຊ່ອງທາງຕິດຕໍ່' => 'สิทธิของลูกค้าและช่องทางติดต่อ',
    'ລູກຄ້າສາມາດຕິດຕໍ່ທີມງານເພື່ອຂໍກວດສອບ, ແກ້ໄຂ ຫຼື ລຶບຂໍ້ມູນການຕິດຕໍ່ຂອງຕົນເອງໄດ້ທຸກເວລາ ໃນເວລາທຳການ ຈັນ–ເສົາ 8:30–17:00:' => 'ลูกค้าติดต่อทีมงานเพื่อขอตรวจสอบ แก้ไข หรือลบข้อมูลการติดต่อของตนเองได้ ในเวลาทำการ จันทร์–เสาร์ 8:30–17:00:',
    'ໂທລະສັບ (ຄຣິກເພື່ອໂທເລີຍ):' => 'โทรศัพท์ (คลิกเพื่อโทร):',
    'ຂອບເຂດການໃຫ້ບໍລິການ' => 'ขอบเขตการให้บริการ',
    '%s ໃຫ້ບໍລິການພັດທະນາ ແລະ ຕິດຕັ້ງລະບົບຂາຍໜ້າຮ້ານ (POS), ຈຳໜ່າຍອຸປະກອນ POS ຄົບຊຸດ ແລະ ພັດທະນາເວັບໄຊ ສຳລັບຮ້ານຄ້າ ແລະ ທຸລະກິດໃນ ສປປ ລາວ.' => '%s ให้บริการพัฒนาและติดตั้งระบบขายหน้าร้าน (POS) จำหน่ายอุปกรณ์ POS ครบชุด และพัฒนาเว็บไซต์ สำหรับร้านค้าและธุรกิจใน สปป.ลาว',
    'ຕິດຕັ້ງລະບົບ ແລະ ຕັ້ງຄ່າອຸປະກອນພ້ອມໃຊ້ງານ ໂດຍທີມງານຜູ້ຊ່ຽວຊານ.' => 'ติดตั้งระบบและตั้งค่าอุปกรณ์พร้อมใช้งาน โดยทีมผู้เชี่ยวชาญ',
    'ຝຶກອົບຮົມການໃຊ້ງານໃຫ້ເຈົ້າຂອງຮ້ານ ແລະ ພະນັກງານ ພ້ອມຄູ່ມືພາສາລາວ.' => 'อบรมการใช้งานให้เจ้าของร้านและพนักงาน พร้อมคู่มือภาษาลาว',
    'ໃຫ້ຄຳປຶກສາ ແລະ ຊ່ວຍເຫຼືອດ້ານເຕັກນິກໃນເວລາທຳການ ຈັນ–ເສົາ 8:30–17:00.' => 'ให้คำปรึกษาและช่วยเหลือด้านเทคนิคในเวลาทำการ จันทร์–เสาร์ 8:30–17:00',
    'ການສອບຖາມລາຄາ ແລະ ການສັ່ງຊື້' => 'การสอบถามราคาและการสั่งซื้อ',
    'ລາຄາສິນຄ້າ, ອຸປະກອນ POS ແລະ ແພັກເກດລະບົບ ແມ່ນບໍ່ສະແດງຢູ່ໜ້າເວັບໄຊ — ລູກຄ້າສາມາດຕິດຕໍ່ສອບຖາມລາຄາ ແລະ ຂໍໃບສະເໜີລາຄາໂດຍກົງນຳທີມງານ ເພື່ອຮັບຂໍ້ສະເໜີທີ່ເໝາະສົມກັບທຸລະກິດ.' => 'ราคาสินค้า อุปกรณ์ POS และแพ็กเกจระบบ ไม่แสดงบนเว็บไซต์ — ลูกค้าติดต่อสอบถามราคาและขอใบเสนอราคาโดยตรงกับทีมงาน เพื่อรับข้อเสนอที่เหมาะกับธุรกิจ',
    'ທຸກຄຳສັ່ງຊື້ ຈະມີພະນັກງານຢືນຢັນລາຍການອຸປະກອນ ແລະ ສະຖານທີ່ຈັດສົ່ງ/ຕິດຕັ້ງກ່ອນທຸກຄັ້ງ.' => 'ทุกคำสั่งซื้อ จะมีพนักงานยืนยันรายการอุปกรณ์และสถานที่จัดส่ง/ติดตั้งก่อนทุกครั้ง',
    'ການຕິດຕັ້ງ ແລະ ການຝຶກອົບຮົມ' => 'การติดตั้งและการฝึกอบรม',
    'ບໍລິການຕິດຕັ້ງເຖິງສະຖານທີ່ ຫຼື ຜ່ານລະບົບອອນລາຍ (Remote) ຕາມຄວາມສະດວກຂອງລູກຄ້າ.' => 'บริการติดตั้งถึงที่ หรือผ่านระบบออนไลน์ (Remote) ตามความสะดวกของลูกค้า',
    'ສອນການໃຊ້ງານຕັ້ງແຕ່ການເພີ່ມສິນຄ້າ, ການຂາຍໜ້າຮ້ານ, ການຕັດສະຕັອກ ຈົນເຖິງການເບິ່ງລາຍງານຍອດຂາຍ.' => 'สอนใช้งานตั้งแต่การเพิ่มสินค้า การขายหน้าร้าน การตัดสต็อก จนถึงการดูรายงานยอดขาย',
    'ການຮັບປະກັນອຸປະກອນ ແລະ ການດູແລຫຼັງການຂາຍ' => 'การรับประกันอุปกรณ์และการดูแลหลังการขาย',
    'ອຸປະກອນ POS ທຸກຊະນິດມີການຮັບປະກັນຕາມເງື່ອນໄຂມາດຕະຖານ (ກໍລະນີເກີດຈາກຄວາມຜິດພາດຂອງໂຮງງານຜະລິດ) ພ້ອມບໍລິການກວດເຊັກ ແລະ ແກ້ໄຂ.' => 'อุปกรณ์ POS ทุกชนิดมีการรับประกันตามเงื่อนไขมาตรฐาน (กรณีเกิดจากความผิดพลาดของโรงงานผลิต) พร้อมบริการตรวจเช็กและแก้ไข',
    'ດູແລລະບົບຊອບແວ ແລະ ໃຫ້ຄຳປຶກສາຕະຫຼອດອາຍຸການໃຊ້ງານແພັກເກດ.' => 'ดูแลระบบซอฟต์แวร์และให้คำปรึกษาตลอดอายุการใช้งานแพ็กเกจ',
    '%s — ຕິດຕໍ່ສອບຖາມລາຄາ ແລະ ສັ່ງຊື້ໄດ້ທີ່ %s' => '%s — ติดต่อสอบถามราคาและสั่งซื้อได้ที่ %s',
    'ກັບໄປໜ້າສິນຄ້າ' => 'กลับไปหน้าสินค้า',
    'ສົນໃຈສິນຄ້າ %s' => 'สนใจสินค้า %s',
    'ລະຫັດສິນຄ້າ: %s' => 'รหัสสินค้า: %s',
    'ພ້ອມຈັດສົ່ງ' => 'พร้อมจัดส่ง',
    'ຈັດສົ່ງທົ່ວປະເທດລາວ' => 'จัดส่งทั่วประเทศลาว',
    'ກວດສອບສະລິບ & ສົ່ງໄວ' => 'ตรวจสอบสลิป & ส่งไว',
    'ສອບຖາມລາຄາ ແລະ ປຶກສາຟຣີ' => 'สอบถามราคาและปรึกษาฟรี',
    'ແຊັດສອບຖາມ' => 'แชทสอบถาม',
    'ພັດທະນາລະບົບ POS, ເວັບໄຊ ແລະ ແອັບມືຖື ພ້ອມດູແລ 24 ຊົ່ວໂມງ' => 'พัฒนาระบบ POS เว็บไซต์ และแอปมือถือ พร้อมดูแล 24 ชั่วโมง',
    'ສະບາຍດີ ສົນໃຈບໍລິການ' => 'สวัสดี สนใจบริการ',
    'ສົນໃຈ %s' => 'สนใจ %s',
    'ສອບຖາມ →' => 'สอบถาม →',
    'ບໍ່ເຫັນສິ່ງທີ່ຕ້ອງການ?' => 'ไม่เห็นสิ่งที่ต้องการ?',
    'ບອກພວກເຮົາ — ລູກຄ້າຕ້ອງການແນວໃດ ພວກເຮົາເຮັດໃຫ້ໄດ້' => 'บอกเรา — ลูกค้าต้องการแบบไหน เราทำให้ได้',
    'ຂໍໃບສະເໜີລາຄາ →' => 'ขอใบเสนอราคา →',
    'ບໍ່ພົບລາຍການທີ່ເລືອກ' => 'ไม่พบรายการที่เลือก',
    'ບໍ່ພົບຂໍ້ມູນທີ່ທ່ານຕ້ອງການ.' => 'ไม่พบข้อมูลที่คุณต้องการ',
    'ກັບໄປໜ້າຫຼັກ' => 'กลับไปหน้าหลัก',
    'ສົນໃຈ %s (%s)' => 'สนใจ %s (%s)',
    'ເບິ່ງຮູບເຕັມຈໍ' => 'ดูรูปเต็มจอ',
    'ຮູບກ່ອນໜ້າ' => 'รูปก่อนหน้า',
    'ຮູບຖັດໄປ' => 'รูปถัดไป',
    'ຮູບທີ %d' => 'รูปที่ %d',
    'ມີສິນຄ້າພ້ອມຈັດສົ່ງ' => 'มีสินค้าพร้อมจัดส่ง',
