    'ເບີໂທຕິດຕໍ່ / WhatsApp (ເພື່ອຮັບແຈ້ງລາຄາ) *' => 'เบอร์โทรติดต่อ / WhatsApp (เพื่อรับแจ้งราคา) *',
    'ຂໍ້ຄວາມເພີ່ມເຕີມ / ສິ່ງທີ່ຕ້ອງການຖາມ (ບໍ່ບັງຄັບ)' => 'ข้อความเพิ่มเติม / สิ่งที่ต้องการถาม (ไม่บังคับ)',
    'ເຊັ່ນ: ຂໍລາຄາສົ່ງ, ໃຊ້ກັບຄອມ ຫຼື ມືຖື, ຕ້ອງການໃຫ້ຈັດສົ່ງຕ່າງແຂວງ...' => 'เช่น: ขอราคาส่ง, ใช้กับคอมหรือมือถือ, ต้องการส่งต่างแขวง...',
    'ລະບຸທີ່ຢູ່ຈັດສົ່ງ ແລະ ບໍລິສັດຂົນສົ່ງໄວ້ລ່ວງໜ້າ (ບໍ່ບັງຄັບ — ແຈ້ງຕອນຕົກລົງລາຄາແລ້ວກໍໄດ້)' => 'ระบุที่อยู่จัดส่งและบริษัทขนส่งล่วงหน้า (ไม่บังคับ — แจ้งตอนตกลงราคาแล้วก็ได้)',
    'ແຂວງ / ນະຄອນຫຼວງ' => 'แขวง / นครหลวง',
