    'ເຊັ່ນ: ສາຂາ ດົງໂດກ, ສາຂາ ປາກເຊ...' => 'เช่น: สาขาดงโดก, สาขาปากเซ...',
    'ລາຍລະອຽດທີ່ຢູ່ເພີ່ມເຕີມ' => 'รายละเอียดที่อยู่เพิ่มเติม',
    'ເຊັ່ນ: ຮ່ອມ, ຈຸດສັງເກດ...' => 'เช่น: ซอย, จุดสังเกต...',
    'ຍັງບໍ່ມີການເກັບເງິນໃນຂັ້ນຕອນນີ້ — ທີມງານຈະຕິດຕໍ່ແຈ້ງລາຄາພິເສດໃຫ້ທ່ານທາງ WhatsApp / ໂທລະສັບ ທັນທີ.' => 'ยังไม่มีการเก็บเงินในขั้นตอนนี้ — ทีมงานจะติดต่อแจ้งราคาพิเศษทาง WhatsApp / โทรศัพท์ทันที',
    'ຂໍໃບສະເໜີລາຄາ / ໃຫ້ທີມງານຕິດຕໍ່ກັບ' => 'ขอใบเสนอราคา / ให้ทีมงานติดต่อกลับ',
