    'ສົນໃຈລະບົບ ຮ້ານເຄື່ອງດື່ມ ແລະ ຄາເຟ' => 'สนใจระบบร้านเครื่องดื่มและคาเฟ่',
    'ພັດທະນາລະບົບຂາຍໜ້າຮ້ານ POS ໃຫ້ເໝາະກັບທຸລະກິດຂອງທ່ານ: ຂາຍ, ສະຕັອກ, ລາຍງານ, ຫຼາຍສາຂາ ພ້ອມຕິດຕັ້ງຟຣີ ແລະ ສອນໃຊ້ງານໃຫ້ຟຣີ.' => 'พัฒนาระบบขายหน้าร้าน POS ให้เหมาะกับธุรกิจของคุณ: ขาย สต็อก รายงาน หลายสาขา พร้อมติดตั้งฟรีและสอนใช้งานฟรี',
    'ຕົວຢ່າງ: ຕິດຕັ້ງລະບົບ POS ຮ້ານກາເຟ ແລະ ຮ້ານອາຫານ' => 'ตัวอย่าง: ติดตั้งระบบ POS ร้านกาแฟและร้านอาหาร',
    'ຕົວຢ່າງການສະແດງຜົນງານ — ແທນດ້ວຍຮູບ ແລະ ລາຍລະອຽດການໄປຕິດຕັ້ງລະບົບໃຫ້ລູກຄ້າແທ້: ຊື່ຮ້ານ, ສະຖານທີ່, ອຸປະກອນທີ່ຕິດຕັ້ງ ແລະ ການສອນພະນັກງານ.' => 'ตัวอย่างการแสดงผลงาน — แทนด้วยรูปและรายละเอียดการติดตั้งจริง: ชื่อร้าน สถานที่ อุปกรณ์ที่ติดตั้ง และการสอนพนักงาน',
    'ຕິດຕັ້ງຟຣີ ສອນໃຊ້ງານໃຫ້ຟຣີ ດູແລ 24 ຊົ່ວໂມງ' => 'ติดตั้งฟรี สอนใช้งานฟรี ดูแล 24 ชั่วโมง',
    'ຄົບຈົບໃນບ່ອນດຽວ' => 'ครบจบในที่เดียว',
    'ລົງທະບຽນຫຼາຍເກີນໄປຈາກເຄື່ອງນີ້ ກະລຸນາລອງໃໝ່ໃນ 1 ຊົ່ວໂມງ' => 'ลงทะเบียนจากเครื่องนี้มากเกินไป กรุณาลองใหม่ใน 1 ชั่วโมง',
    'ອໍເດີນີ້ປິດແລ້ວ ແນບສະລິບບໍ່ໄດ້' => 'คำสั่งซื้อนี้ปิดแล้ว แนบสลิปไม่ได้',
    'ຕິດຕັ້ງຟຣີ ສອນໃຊ້ງານໃຫ້ຟຣີ ແລະ ຮັບປະກັນ' => 'ติดตั้งฟรี สอนใช้งานฟรี และรับประกัน',
    'ທີມງານຕັ້ງຄ່າ ຕິດຕັ້ງຟຣີ ສອນໃຊ້ງານໃຫ້ຟຣີ ແລະ ດູແລຫຼັງການຂາຍຕະຫຼອດອາຍຸການໃຊ້ງານ.' => 'ทีมงานตั้งค่า ติดตั้งฟรี สอนใช้งานฟรี และดูแลหลังการขายตลอดอายุการใช้งาน',
    'ຕິດຕັ້ງຟຣີ ແລະ ສອນໃຊ້ງານໃຫ້ຟຣີໂດຍທີມງານ WlaoDev' => 'ติดตั้งฟรีและสอนใช้งานฟรีโดยทีมงาน WlaoDev',
    'ສະເພາະໂປຣແກຣມ' => 'เฉพาะโปรแกรม',
    'ເໝາະສຳລັບຮ້ານທີ່ມີຄອມພິວເຕີ ຫຼື ແທັບເລັດຢູ່ແລ້ວ ຕ້ອງການສະເພາະລະບົບໂປຣແກຣມ' => 'เหมาะสำหรับร้านที่มีคอมพิวเตอร์หรือแท็บเล็ตอยู่แล้ว ต้องการเฉพาะโปรแกรม',
    'ໂປຣແກຣມ POS ລິຂະສິດແທ້ ໃຊ້ງານຕະຫຼອດຊີບ (ບໍ່ມີຄ່າລາຍເດືອນ)' => 'โปรแกรม POS ลิขสิทธิ์แท้ ใช้งานตลอดชีพ (ไม่มีค่ารายเดือน)',
    'ຮອງຮັບ 1 ຈຸດຂາຍ (ສາມາດເພີ່ມຈຸດຂາຍໄດ້)' => 'รองรับ 1 จุดขาย (เพิ่มจุดขายได้)',
    'ລະບົບຂາຍ, ຕັດສະຕັອກ, ສະມາຊິກ ແລະ ລາຍງານຄົບຊຸດ' => 'ระบบขาย ตัดสต็อก สมาชิก และรายงานครบชุด',
    'ຕິດຕັ້ງຟຣີ ແລະ ສອນໃຊ້ງານໃຫ້ຟຣີ' => 'ติดตั้งฟรีและสอนใช้งานฟรี',
    'ທີມງານຊ່ວຍເຫຼືອ ແລະ ດູແລລະບົບຕະຫຼອດການໃຊ້ງານ' => 'ทีมงานช่วยเหลือและดูแลระบบตลอดการใช้งาน',
    'ຊຸດຍອດນິຍົມ ⭐' => 'ชุดยอดนิยม ⭐',
    'ຊຸດຄົບເຄື່ອງພ້ອມຂາຍ: ໂປຣແກຣມ + ເຄື່ອງພິມບິນ + ລິ້ນຊັກເກັບເງິນ' => 'ชุดพร้อมขาย: โปรแกรม + เครื่องพิมพ์บิล + ลิ้นชักเก็บเงิน',
    'ໂປຣແກຣມ POS ລິຂະສິດແທ້ ໃຊ້ງານຕະຫຼອດຊີບ' => 'โปรแกรม POS ลิขสิทธิ์แท้ ใช้งานตลอดชีพ',
    'ເຄື່ອງພິມໃບບິນຄວາມຮ້ອນ 80mm ຕັດເຈ້ຍອັດຕະໂນມັດ (Thermal Printer)' => 'เครื่องพิมพ์ใบเสร็จความร้อน 80mm ตัดกระดาษอัตโนมัติ (Thermal Printer)',
    'ລິ້ນຊັກເກັບເງິນເຫຼັກໜາ 5 ຊ່ອງທະນະບັດ ເດັ້ງອັດຕະໂນມັດ (Cash Drawer)' => 'ลิ้นชักเก็บเงินเหล็กหนา 5 ช่องธนบัตร เด้งอัตโนมัติ (Cash Drawer)',
    'ເຈ້ຍພິມບິນຄວາມຮ້ອນແຖມຟຣີ 5 ກໍ້' => 'แถมกระดาษพิมพ์บิลความร้อนฟรี 5 ม้วน',
    'ຮັບປະກັນອຸປະກອນ 1 ປີເຕັມ' => 'รับประกันอุปกรณ์ 1 ปีเต็ม',
    'ຊຸດຄົບວົງຈອນລະດັບມືອາຊີບ' => 'ชุดครบวงจรระดับมืออาชีพ',

    // ບັນຊີ, ອໍເດີ, ໜ້າລະບົບ POS, ຕິດຕໍ່ (10/11/2026)
    'ຊຸດໃຫຍ່ຄົບເຊັດ: ເຄື່ອງ POS Touchscreen Dual Screen + ປິ້ນເຕີ + ເຄື່ອງຍິງບາໂຄດ + ລິ້ນຊັກ' => 'ชุดใหญ่ครบเซ็ต: เครื่อง POS ทัชสกรีน 2 จอ + ปริ้นเตอร์ + เครื่องยิงบาร์โค้ด + ลิ้นชัก',
    'ເຄື່ອງ POS Touchscreen ຈໍສຳຜັດ Dual Screen (ຈໍຫຼັກ 15.6" + ຈໍລູກຄ້າ)' => 'เครื่อง POS ทัชสกรีน 2 จอ (จอหลัก 15.6" + จอลูกค้า)',
    'ເຄື່ອງພິມໃບບິນ 80mm High Speed ຕັດເຈ້ຍອັດຕະໂນມັດ' => 'เครื่องพิมพ์ใบเสร็จ 80mm ความเร็วสูง ตัดกระดาษอัตโนมัติ',
    'ເຄື່ອງສະແກນບາໂຄດ 1D/2D ອ່ານໄວແມ່ນຍຳ' => 'เครื่องสแกนบาร์โค้ด 1D/2D อ่านเร็วแม่นยำ',
    'ລິ້ນຊັກເກັບເງິນເຫຼັກໜາລະບົບ Heavy Duty' => 'ลิ้นชักเก็บเงินเหล็กหนา Heavy Duty',
    'ຕິດຕັ້ງຟຣີ, ສອນໃຊ້ງານໃຫ້ຟຣີ ແລະ ດູແລພິເສດ VIP' => 'ติดตั้งฟรี สอนใช้งานฟรี และดูแลพิเศษ VIP',
    'ຮັບປະກັນອຸປະກອນ 1 ປີ ພ້ອມເຄື່ອງສຳຮອງປ່ຽນທັນທີ' => 'รับประกันอุปกรณ์ 1 ปี พร้อมเครื่องสำรองเปลี่ยนทันที',
    'ໃຊ້ເປັນແນ່ນອນ — ໜ້າຈໍກົດງ່າຍຄືໃຊ້ມືຖື ພວກເຮົາຕິດຕັ້ງຟຣີ ແລະ ສອນໃຊ້ງານໃຫ້ຟຣີຈົນພະນັກງານຂາຍເອງໄດ້ ສ່ວນຫຼາຍໃຊ້ເປັນພາຍໃນມື້ດຽວ.' => 'ใช้เป็นแน่นอน — หน้าจอกดง่ายเหมือนใช้มือถือ เราติดตั้งฟรีและสอนใช้งานฟรีจนพนักงานขายเองได้ ส่วนใหญ่ใช้เป็นภายในวันเดียว',
    'ມີທີມງານຊ່ຽວຊານຕິດຕັ້ງຟຣີ ແລະ ສອນໃຊ້ງານໃຫ້ຟຣີເຖິງສະຖານທີ່ຂອງທ່ານ (ຫຼື ຜ່ານອອນລາຍ) ພ້ອມຄູ່ມືພາສາລາວ ແລະ ວິດີໂອສອນທຸກຂັ້ນຕອນ.' => 'มีทีมงานผู้เชี่ยวชาญติดตั้งฟรีและสอนใช้งานฟรีถึงสถานที่ของคุณ (หรือออนไลน์) พร้อมคู่มือภาษาลาวและวิดีโอสอนทุกขั้นตอน',
