    'ລືມລະຫັດຜ່ານ? ເພີ່ມອີເມວໃນ "ຂໍ້ມູນຕິດຕໍ່" ກ່ອນ ຫຼື ຕິດຕໍ່ທີມງານທາງ WhatsApp' => 'ลืมรหัสผ่าน? เพิ่มอีเมลใน "ข้อมูลติดต่อ" ก่อน หรือติดต่อทีมงานทาง WhatsApp',
    'ສົ່ງລະຫັດຜ່ານໃໝ່ໄປອີເມວຂອງທ່ານ? ລະຫັດເກົ່າຈະໃຊ້ບໍ່ໄດ້ອີກ' => 'ส่งรหัสผ่านใหม่ไปอีเมลของคุณ? รหัสเดิมจะใช้ไม่ได้อีก',
