    'ປ້ອນລະຫັດຜ່ານເກົ່າຜິດຫຼາຍເກີນໄປ ກະລຸນາລອງໃໝ່ໃນ 1 ຊົ່ວໂມງ ຫຼື ກົດ "ລືມລະຫັດຜ່ານ"' => 'ใส่รหัสเดิมผิดหลายครั้งเกินไป กรุณาลองใหม่ใน 1 ชั่วโมง หรือกด "ลืมรหัสผ่าน"',
