    'ສົ່ງລະຫັດຜ່ານໃໝ່ໄປທີ່ %s ແລ້ວ — ໃຊ້ລະຫັດນັ້ນເຂົ້າສູ່ລະບົບໄດ້ເລີຍ ຫຼື ປ້ອນເປັນລະຫັດເກົ່າເພື່ອຕັ້ງລະຫັດຂອງທ່ານເອງ' => 'ส่งรหัสผ่านใหม่ไปที่ %s แล้ว — ใช้เข้าสู่ระบบได้เลย หรือใส่เป็นรหัสเดิมเพื่อตั้งรหัสของคุณเอง',
    'ເພີ່ມອີເມວໃນ "ຂໍ້ມູນຕິດຕໍ່" ກ່ອນ ຈຶ່ງຮັບແຈ້ງເຕືອນໄດ້' => 'เพิ่มอีเมลใน "ข้อมูลติดต่อ" ก่อนจึงจะรับการแจ้งเตือนได้',
